COLLDATA("sh21494","ur",[[601,"سیدنا براء بن عازب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز شروع کرتے تو اپنے دونوں ہاتھوں کو اٹھاتے یہاں تک کہ وہ آپ کے کانوں کے قریب ہو جاتے پھر ان کو نہ اٹھاتے یہاں تک کہ سلام پھیر دیتے۔","",{"t":"نماز میں عدم رفع الیدین کی دلیل","k":"إسناده ضعیف: سنن ابی داؤد، ح: 749۔ یزید بن ابی زیاد اور ابن ابی لیلی ضعیف ہے۔ صحیح البخاری کی حدیث (738 عن مالک بن الحویرث 737 عن ابن عمر) اس سے بے نیاز کر دیتی ہے۔"}],[602,"سیدنا ابو ہریرہ رضی اللہ عنہ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم علی بن ابی طالب رضی اللہ عنہ کا سہارا لیے ہوئے باہر تشریف لائے تو انہیں ابو بکر اور عمر ملے۔ انہیں دیکھ کر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے علی! ان دونوں سے محبت کرو جنت میں داخل ہو جاؤ گے۔\"","",{"t":"سیدنا ابو بکر و عمر رضی اللہ عنہما کی محبت","k":"إسناده ضعیف: تاریخ دمشق (223/44)۔ محمد بن احمد بن سعید بن فرقد اور عمرو بن حفص البصری ضعیف ہیں، اس کے دیگر طرق بھی ضعیف ہیں۔"}],[603,"سیدنا سنان بن سنہ الاسلمی رضی اللہ عنہ جو کہ نبی صلی اللہ علیہ وسلم کے صحابی ہیں۔ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کھانا کھا کر شکر ادا کرنے والے کے لیے صبر کرنے والے روزے دار کے برابر اجر ہے۔\"","",{"t":"کھانے کے بعد شکر ادا کرنے کی فضیلت","k":"صحیح: سنن ابن ماجہ، ح: 1765۔ مسند احمد (343/4)۔ سنن الدارمی، ح: 2024۔ مسند الشہاب، ح: 264۔","f":"کھا پی کر اللہ تعالی کا شکر ادا کرنے والے شخص کی فضیلت بیان ہو رہی ہے کہ اسے اللہ تعالی کی بارگاہ سے اتنا اجر و ثواب ملتا ہے جتنا صبر کرنے والے روزے دار کے لیے ہے۔\nعلماء کا کہنا ہے کہ ادائیگی شکر کا اولی درجہ یہ ہے کہ انسان کھانا شروع کرتے وقت بسم اللہ پڑھے اور اگر بھول جائے تو درمیان میں \"بسم اللہ فی اولہ و آخرہ\" پڑھے جیسا کہ حدیث میں ہے۔ (سنن الترمذی، ح: ۱۸۵۸ حسن) اور کھانے سے فارغ ہو کر اللہ تعالی کی حمد و ثنا بیان کرے۔ جس کا بہترین طریقہ وہ دعا ئیں پڑھنا ہے جن کی رسول اللہ صلی اللہ علیہ وسلم نے ہمیں تعلیم فرمائی ہے جیسے: ((الحمد للہ کثیرا طیبا مبارکا فیہ غیر مکفی ولا مودع ولا مستغنی عنہ ربنا)) \"تمام تعریفیں اللہ کے لیے ہیں، بہت زیادہ پاکیزہ اور بابرکت۔ نہ کفایت کیا گیا (یعنی یہ کھانا اس لحاظ سے کافی نہیں کہ آئندہ اس کی ضرورت نہیں) اور نہ الوداع کہا گیا (یعنی یہ ہماری زندگی کا آخری کھانا نہ ہو) اور اے ہمارے رب! نہ اس سے بے پروائی کی جا سکتی ہے۔\" (صحیح البخاری، ح: ۵۴۵۸) ((الحمد للہ الذی اطعمنی ہذا الطعام ورزقنیہ من غیر حول منی ولا قوة)) \"سب تعریفیں اس اللہ کے لیے ہیں جس نے مجھے یہ کھانا کھلایا اور بغیر میری کسی قوت و کوشش کے مجھے یہ عطا فرمایا۔\" (سنن ابی داؤد، ح: ۴۰۲۳ حسن) شکر کا اعلی درجہ یہ ہے کہ اللہ کی حمد و ثنا بھی کرے اور اس کے ساتھ ساتھ اپنی زندگی شریعت کے دائرے میں بسر کرے، اللہ اور اس کے رسول کی اطاعت و فرمانبرداری کرے۔ غور کا مقام ہے کہ مذکورہ بالا حدیث میں شکر کے ادنی درجہ کی فضیلت بتائی گئی ہے جبکہ شکر کے اعلی درجہ کی فضیلت اس سے کہیں بڑھ کر ہے۔"}],[604,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ انصار میں سے ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کی مجلس میں بیٹھا کرتا تھا۔ وہ آپ سے حدیث سنتا اور اسے پسند کرتا (لیکن اسے) یاد نہ رکھ پاتا۔ تو اس نے اس کی رسول اللہ صلی اللہ علیہ وسلم سے شکایت کی۔ میرا خیال ہے کہ میری کتاب سے (کچھ الفاظ) ساقط ہو گئے ہیں تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"اپنے ہاتھ کے ذریعے سے مدد حاصل کرو۔\" اور آپ نے اپنے ہاتھ سے لکھنے کا اشارہ فرمایا۔","",{"t":"احادیث لکھنے کی اجازت","k":"إسناده ضعیف: سنن الترمذی، ح: 2666۔ خلیل بن مرة ضعیف اور یحیی بن ابی صالح مجہول ہے۔"}],[605,"سیدنا انس رضی اللہ عنہ فرماتے ہیں کہ نبی صلی اللہ علیہ وسلم گندمی رنگ والے تھے۔","",{"t":"نبی صلی اللہ علیہ وسلم کی رنگت","k":"صحیح: سنن الترمذی، ح: 1754۔ مسند احمد: (258/3)،(259)۔ صحیح ابن حبان، ح: 6286۔ مسند ابی یعلی، ح: 3741۔","f":"امام بیہقی رحمہ اللہ فرماتے ہیں کہ آپ صلی اللہ علیہ وسلم کے جسم مبارک کا جو حصہ دھوپ اور ہوا کے سامنے ہوتا تھا وہ سفید سرخی مائل تھا اور جس حصے پر براہ راست دھوپ اور ہوا نہیں پڑتی تھی وہ بہت زیادہ سفید اور چمک دار تھا۔ دلائل النبوة: ۲۳۹/۱، تحت، ح: ۲۵۰۔ نیز دیکھیے: شمائل ترمذی، ص: (۴۸)،(۴۹) تحقیق شیخنا زبیر علی زئی رحمہ اللہ"}],[606,"سیدنا عیاض بن حمار المجاشعی رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بے شک اللہ نے زمین والوں کی طرف نظر فرمائی تو اہل کتاب کے کچھ بچے کچھ لوگوں کے سوا باقی عرب و عجم سب پر وہ ناراض ہوا۔ اور اس نے فرمایا: درحقیقت میں نے آپ کو مبعوث فرمایا ہے تاکہ میں آپ کی اور آپ کے ذریعے سے دوسروں کی آزمائش کروں اور میں نے آپ پر ایک ایسی کتاب نازل فرمائی ہے جسے پانی دھو (کر مٹا) نہیں سکتا۔ آپ اسے سوتے ہوئے اور جاگتے ہوئے (ہر حال میں) پڑھیں گے۔\"","",{"t":"قرآن مجید ہر حال میں پڑھنا","k":"صحیح مسلم، ح: 2865۔ المعجم الاوسط، ح: 2933۔ السنن الکبری للنسائی، ح: 8016۔ مسند البزار، ح: 3491۔","f":"اٹھتے بیٹھتے چلتے پھرتے ہر حال میں تلاوت قرآن جائز ہے بشرط یہ کہ بندہ جنبی نہ ہو۔ (تفصیل کے لیے ملاحظہ کریں فتاوی علیہ ۲۰۲/۱ تا ۲۰۴)\nلوگوں کی اکثریت اللہ تعالی کو غصہ دلاتی ہے بہت کم لوگ ہیں جو اسے خوش کرتے ہو۔\nاللہ تعالی نے انبیاء کرام کی بعثت کے ذریعے لوگوں کا امتحان لیا ہے جو ایمان لائے اور نبیوں کی تعلیمات پر چلے وہ کامیاب اور جنہوں نے انکار کیا وہ ناکام ہوئے ہیں۔\nقرآن مجید قیامت تک کے لیے ہر قسم کی تحریف سے محفوظ کتاب ہے اس کی حفاظت کا ذمہ اللہ تعالی نے لے رکھا ہے۔"}],[607,"عمرو بن میمون کہتے ہیں کہ عبد اللہ رضی اللہ عنہ پر سال گزر جاتا وہ رسول اللہ صلی اللہ علیہ وسلم سے ایک بھی حدیث بیان نہ کرتے۔ راوی کہتا ہے: پھر ایک دن انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے ایک حدیث بیان کی تو ان کا چہرہ متغیر ہو گیا اور انہوں نے کہا: (شاید آپ صلی اللہ علیہ وسلم نے) یہ الفاظ بیان کیے، یا ان سے زیادہ، یا ان سے کچھ کم، یا اسی طرح بیان فرمایا تھا۔","",{"t":"روایت حدیث میں احتیاط","k":"صحیح: سنن ابن ماجہ، ح: 23۔ المعجم الکبیر، ح: 8615۔ مسند البزار، ح: 1862۔ المستدرک للحاکم (111/1)۔ مسند احمد (452/1)۔","f":"یہ صحابہ کرام کا کمال ادب و احتیاط تھا کہ وہ روایت حدیث میں نبی صلی اللہ علیہ وسلم کی طرف کسی بات کی اس وقت تک نسبت نہ کرتے جب تک خوب یقین نہ ہو جاتا کہ آپ کا یہی فرمودہ ہے اور جب ذرا سا بھی شبہ و گمان ہوتا تو اس خوف سے ڈر جاتے کہ مبادا آپ صلی اللہ علیہ وسلم پر جھوٹ نہ باندھ بیٹھیں۔"}],[608,"اسماعیل بن ابی خالد کہتے ہیں کہ میں نے شعبی کو سنا، وہ ایک آدمی سے، وہ ابو طلحہ کی بیوی سعدی المری سے روایت کرتے ہیں کہ عمر بن خطاب رضی اللہ عنہ عبید اللہ بن طلحہ کے پاس سے گزرے۔ یہ اس وقت کی بات ہے جب ابو بکر رضی اللہ عنہ کو خلیفہ منتخب کیا گیا۔ تو انہوں نے کہا: مجھے کیا ہے کہ میں آپ کو پریشان دیکھ رہا ہوں۔ شاید آپ اپنے چچا زاد (ابو بکر) کی امارت کو ناپسند کرتے ہیں؟ انہوں نے کہا: نہیں (ایسی بات نہیں)۔ لیکن میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک کلمہ کہتے سنا تھا، میں آپ صلی اللہ علیہ وسلم سے اس کے بارے میں پوچھ نہیں سکا یہاں تک کہ آپ وفات پا گئے۔ آپ نے فرمایا تھا: \"بے شک میں ایک ایسا کلمہ جانتا ہوں جسے کوئی بھی آدمی اپنی موت کے وقت ادا کر لے تو اس کے نامہ اعمال میں نور ہو گا اور بے شک اس کی روح کی اس کی موت کے وقت راحت پائے گی۔\" یہ سن کر عمر نے کہا: بے شک میں اس (کلمہ) کو جانتا ہوں، وہ لا الہ الا اللہ ہے اور یہی وہ کلمہ ہے جسے آپ نے اپنے چچا پر پیش کیا تھا۔ میں تو یہی سمجھتا ہوں۔","",{"t":"لا الہ الا اللہ کی فضیلت","k":"صحیح: سنن ابن ماجہ، ح: 3795۔ مسند البزار، ح: 840۔ مسند احمد (161/1)۔ المستدرک للحاکم (351/1)۔","f":"سیدنا طلحہ بن عبید اللہ رضی اللہ عنہ خلافت صدیقی سے بالکل راضی اور خوش تھے۔\nکلمہ طیبہ کی بڑی فضیلت ہے۔\nجس نے موت کے وقت کلمہ پڑھ لیا وہ دوزخ سے نجات پا جائے گا۔\nنبی کریم صلی اللہ علیہ وسلم کو اپنے چچا ابو طالب سے نہایت الفت تھی آپ چاہتے تھے کہ وہ آخرت کے عذاب سے بچ جائیں اس لیے آپ نے ان کی موت کے وقت انہیں کلمہ پڑھنے کے لیے کہا لیکن انہوں نے انکار کر دیا تھا۔ (دیکھیے: صحیح البخاری، ح: ۴۷۷۲)\nدینی مسائل دریافت کرنے کے سلسلے میں سستی کا شکار نہیں ہونا چاہیے۔"}],[609,"شعبہ، ادریس الاودی سے، وہ اپنے والد سے، وہ ابو ہریرہ رضی اللہ عنہ سے روایت کرتے ہیں۔ شعبہ کہتے ہیں کہ میں نے کہا: وہ نبی صلی اللہ علیہ وسلم سے (مرفوعا) روایت کرتے ہیں؟ انہوں نے کہا: میں اسے اپنے زیادہ تر علم کے مطابق یہ سمجھتا ہوں کہ انہوں نے کہا کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی شخص اس حال میں ہرگز نماز نہ پڑھے جب اسے نجاست میں سے کوئی چیز لاحق ہو۔\" اور انہوں نے کہا: وہم کی صورت میں پور غور و فکر کر کے درست چیز تک پہنچنے کی کوشش کرے۔","",{"t":"بول و براز روک کر نماز پڑھنے کی ممانعت","k":"صحیح: سنن ابن ماجہ، ح: 618۔ مسند اسحاق بن راہویہ، ح: 467۔ المصنف لابن ابی شیبة، ح: 8018۔","f":"یعنی جب بول و براز کی حاجت ہو تو ایسی صورت میں نماز نہیں پڑھنی چاہیے، کیونکہ اس سے نہ صرف نماز کا خشوع و خضوع متاثر ہو گا بلکہ یہ چیز صحت پر بھی اثر انداز ہو سکتی ہے۔ اس لیے فراغت کے بعد نماز ادا کرے۔"}],[610,"سیدنا مسور بن مخرمہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"جس نے (ناحق) ایک بالشت زمین بھی حاصل کی قیامت کے دن اسے سات زمینوں کا پٹا پہنایا جائے گا۔\"","",{"t":"زمین پر ناجائز قبضہ کرنا","k":"صحیح: مجمع الزوائد، ح: 6890 وقال: رواہ الطبرانی فی الکبیر وفیہ عمران بن ابان الواسطی وثقہ ابن حبان وضعفہ جماعة۔ میں کہتا ہوں کہ شواہد کی بنا پر حدیث صحیح ہے۔ شواہد کے لیے دیکھیے: صحیح البخاری، ح: 3198۔","f":"دیکھیے: حدیث نمبر ۱۰۳۔"}],[611,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: جب وہ (مرد) اس (اپنی بیوی) کی چار شاخوں کے درمیان میں ہو اور ختنے کو ختنے سے ملا دے تو یقینا غسل واجب ہو گیا۔","",{"t":"غسل کب واجب ہوتا ہے","k":"صحیح مسلم، ح: 349۔ سنن الترمذی، ح: 108۔ الموطا للامام مالک، ح: 104۔","f":"مرد کے عضو کا سر (حشفہ) عورت کی شرم گاہ میں غائب ہو جائے تو غسل واجب ہو جاتا ہے۔\nختنے کو ختنے سے ملا دے سے مراد جماع ہے یعنی ذکر شرم گاہ میں غائب ہو جائے۔ محض چھونا مراد نہیں ہے۔ (تفصیل کے لیے دیکھیے: صحیح مسلم مع شرح النووی تحت ح: ۳۴۹)"}],[612,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے کہا: اے اللہ کے رسول! کون سے گناہ سب سے بڑے ہیں؟ آپ نے فرمایا: \"یہ کہ تو اللہ کے ساتھ کسی کو شریک ٹھہرائے حالانکہ اس نے تجھے پیدا کیا ہے۔\" میں نے کہا: پھر کون سا ہے؟ آپ نے فرمایا: \"یہ کہ تو اپنے بچے کو اس ڈر سے قتل کرے کہ وہ تیرے ساتھ کھائے گا۔\" میں نے کہا: پھر کون سا؟ آپ نے فرمایا: \"یہ کہ تو اپنے پڑوسی کی بیوی سے زنا کرے۔\" پھر فرمایا: (ترجمہ:) \"اور وہ جو اللہ کے ساتھ کسی دوسرے معبود کو نہیں پکارتے اور نہ اس جان کو قتل کرتے ہیں جسے اللہ نے حرام ٹھہرایا ہے مگر حق کے ساتھ اور نہ زنا کرتے ہیں اور جو کوئی یہ کرے گا وہ سخت گناہ کو ملے گا۔\" (الفرقان: ۶۸)۔","",{"t":"کبیرہ گناہ","k":"صحیح البخاری، ح: 4761۔ صحیح مسلم، ح: 86۔ سنن ابی داؤد، ح: 2310۔ سنن الترمذی، ح: 3182۔ سنن النسائی، ح: 4018۔","f":"جس گناہ پر دنیا میں کوئی حد مقرر ہو، جیسے: قتل، زنا اور چوری کرنا ہے یا جس کے متعلق آخرت میں عذاب، غصہ، جھٹک وغیرہ کی وعید ہو، یا جس کا کرنے والا نبی صلی اللہ علیہ وسلم کی زبان اطہر سے ملعون گردانا گیا ہو تو بلا شبہ وہ کبیرہ گناہ ہو گا۔ (الکبائر للذہبی، ص: ۸)\nسب سے بڑا اور مہلک ترین گناہ شرک ہے۔\nکسی کو ناحق قتل کرنا اور زنا کرنا بھی کبیرہ گناہ ہے۔ لیکن اپنی اولاد کو اس ڈر سے قتل کرنا کہ وہ میرے ساتھ کھائے گی اور اسی طرح ہمسائے کی بیوی سے زنا کرنا انتہائی کبیرہ ہے۔"}],[613,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ فرماتے ہیں: میں نے کہا: اے اللہ کے رسول! کون سا عمل افضل ہے؟ آپ نے فرمایا: \"نماز کو اس کے وقت پر ادا کرنا۔\"","",{"t":"افضل عمل","k":"صحیح البخاری، ح: 7534۔ صحیح مسلم، ح: 85۔ سنن الترمذی، ح: 173۔ سنن النسائی، ح: 612۔","f":"ایک روایت میں ہے \"الصلاة فی اول وقتہا\" نماز کو اس کے اول وقت میں ادا کرنا۔ (صحیح ابن خزیمہ، ح: ۳۲۷۔ صحیح ابن حبان، ح: ۱۴۷۵ وسندہ صحیح) اس سے معلوم ہوا کہ نماز کو اول وقت میں ادا کرنا افضل عمل ہے۔\nامام ابن خزیمہ رحمہ اللہ فرماتے ہیں کہ اس فرمان سے آپ کی مراد سب نمازوں کے بجائے کچھ نمازیں ہیں اور سب اوقات کے بجائے کچھ اوقات ہیں کیونکہ نبی صلی اللہ علیہ وسلم نے شدید گرمی میں نماز ظہر کو ٹھنڈا کر کے پڑھنے کی خبر دی ہے اور یہ بھی ہے کہ اگر کمزور شخص کی کمزوری اور بیماری کی بیماری کا خیال نہ ہوتا تو آپ عشاء کی نماز کو آدھی رات تک مؤخر کر دیتے۔ (دیکھیے: صحیح ابن خزیمہ، قبل، ح: ۳۲۸)"}],[614,"سیدنا عمرو بن الحمق رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایمان نے دھوکے سے قتل کرنے کو بند کر دیا ہے۔ جس شخص نے کسی آدمی کو اس کے خون کی امان دی پھر اسے قتل کر دیا تو میں قاتل سے لاتعلق ہوں، مقتول اگرچہ کافر ہی ہو۔\"","",{"t":"کسی کو دھوکے سے قتل کرنا","k":"إسناده ضعیف: مسند الشہاب، ح: 164۔ رشید بن سعید ضعیف ہے۔ سنن ابی داؤد (ح: 2769) اور سنن ابن ماجہ (ح: 2688) کی حدیث اس سے بے نیاز کر دیتی ہے۔"}],[615,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے جنین کے بارے میں غلام یا لونڈی یا گھوڑا یا خچر (بطور دیت) ادا کرنے کا فیصلہ فرمایا۔ سلیمان نے ہمیں کہا: عیسی سے میرے علاوہ جو شخص تمہیں یہ حدیث بیان کرے تو اس کی تصدیق مت کرنا۔ یہ سن کر ایک آدمی نے انہیں کہا: وہ کیوں؟ انہوں نے کہا: کیونکہ میں نے ان پر ان کی کتاب سے بیان کیا ہے (اس لیے ان کی احادیث میرے واسطے والی معتبر ہیں) اور انہوں نے مجھ سے وعدہ کیا کہ وہ (اب) اسے بیان نہیں کریں گے۔","",{"t":"جنین کی دیت","k":"صحیح البخاری، ح: 5759۔ صحیح مسلم، ح: 1681۔ سنن ابی داؤد، ح: 4579۔ سنن الترمذی، ح: 2111۔ سنن النسائی، ح: 4823۔ سنن ابن ماجہ، ح: 2639۔","f":"جنین: یہ لفظ \"جن\" سے بنا ہے جس کا معنی چھپنا ہے اور جنین اس بچے کو کہتے ہیں جو ماں کے پیٹ میں ہو کیونکہ وہ چھپا ہوا ہوتا ہے، اگر زندہ پیدا ہو تو اسے ولد اور مردہ پیدا ہو تو سقط کہتے ہیں اور جنین بھی کہہ دیتے ہیں بشرط یہ کہ وہ بچہ بن چکا ہو۔\nغرہ اس سفیدی کو کہتے ہیں جو گھوڑے کی پیشانی پر ہوتی ہے پھر ہر عمدہ اور نفیس چیز کے لیے بھی اسے بول دیا جاتا ہے۔ لیکن یہاں حدیث مبارک میں اس سے مراد غلام ہے مذکر ہو یا مونث۔ غلام کو غرہ اس لیے کہتے ہیں کہ وہ انسان کے مال میں سے سب سے عمدہ اور نفیس مال تصور کیا جاتا تھا۔\nاس حدیث میں گھوڑے یا خچر کا ذکر غیر محفوظ ہے۔ (دیکھیے: السنن الصغری، ح: ۳۰۹۶) امام نووی نے اسے باطل کہا ہے۔ (دیکھیے: صحیح مسلم مع شرح النووی: ۲۸۴/۵، مکتبہ البشری)۔ واللہ اعلم!\nجنین کی دیت ایک غلام یا لونڈی ہے فی زمانہ اس کی قیمت بھی ادا کی جا سکتی ہے۔"}],[616,"رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام ابو رافع رضی اللہ عنہ فرماتے ہیں کہ آپ نے ایک تحریر میرے حوالے کی۔ انہوں (ابو رافع) نے دعوی کیا کہ اس میں رسول اللہ صلی اللہ علیہ وسلم کی نماز شروع کرنے کی دعا بھی تھی۔ کہتے ہیں کہ جب آپ اللہ اکبر کہتے تو فرماتے: ﴿وجہت وجہی للذی فطر السماوات والارض حنیفا وما انا من المشرکین﴾ \"میں نے اپنا چہرہ اس ذات کی طرف متوجہ کر لیا جس نے آسمانوں اور زمین کو پیدا کیا ہے۔ یکسو ہو کر۔ اور میں مشرکوں میں سے نہیں ہوں۔\" ﴿ان صلاتی ونسکی ومحیای ومماتی للہ رب العالمین لا شریک لہ وبذلک امرت وانا من المسلمین﴾ \"بے شک میری نماز، میری قربانی، میری زندگی اور میری موت اللہ کے لیے ہے جو تمام جہانوں کا پروردگار ہے، اس کا کوئی شریک نہیں اور مجھے اسی کا حکم دیا گیا ہے اور میں ماننے والوں میں سب سے پہلا سے ہوں، اے اللہ! تو ہی بادشاہ ہے، تیرے سوا کوئی معبود نہیں، تو پاک ہے، اپنی حمد کے ساتھ، تو میرا رب ہے اور میں تیرا بندہ ہوں، تیرا کوئی شریک نہیں، میں نے اپنی جان پر ظلم کیا اور میں اپنے گناہ کا اعتراف کرتا ہوں لہذا تو مجھے میرے تمام گناہ بخش دے، حقیقت یہ ہے کہ تیرے سوا گناہوں کو کوئی نہیں بخشتا۔ اور مجھے طرف کی طرف ہدایت دے کیونکہ نیک اعمال کی طرف تو ہی ہدایت دیتا ہے اور برے اعمال سے تو ہی پھیرتا ہے، میں سعادت مندی کے ساتھ حاضر ہوں۔ اور تمام خیر تیرے ہاتھ میں ہے اور شر تیری طرف سے نہیں، تیرے سوا تجھ سے بھاگ کر کہیں جانے کی کوئی جگہ نہیں، نہ ہی تیرے سوا تجھ سے بچنے کی کوئی پناہ کی جگہ ہے۔ تو بہت برکت والا اور رفعت اور بلندی والا ہے میں تجھ سے بخشش مانگتا ہوں اور تیری طرف رجوع کرتا ہوں۔\"","",{"t":"دعا استفتاح","k":"صحیح: المعجم الکبیر، ح: 928۔ محمد بن اسحاق مدلس کا عنعنہ ہے۔ دیکھیے: مجمع الزوائد، ح: 2621۔ شواہد کی بنا پر حدیث صحیح ہے۔ شواہد کے لیے دیکھیے: صحیح مسلم، ح: 771۔ سنن الترمذی، ح: 3423۔","f":"مذکورہ دعا فرض اور نفل دونوں میں پڑھ سکتے ہیں۔"}],[617,"امام شعبہ فرماتے ہیں: اگر میں آسمان سے گر کر ٹکڑے ٹکڑے ہو جاؤں تو یہ مجھے اس بات سے زیادہ پسند ہے کہ میں کسی حدیث میں یہ کہوں، جبکہ میں نے وہ اس سے سنی نہ ہو۔ کہ فلاں نے یہ کہا۔","",{"t":"تدلیس کی سنگینی","k":"صحیح: الجرح والتعدیل لابن ابی حاتم (173/1)۔","f":"امام شعبہ تدلیس نہیں کرتے تھے وہ تدلیس کے سخت خلاف تھے۔"}],[618,"سیدنا سہل بن سعد رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے سر میں کثرت سے تیل لگاتے اور پانی لگا کر داڑھی کی کنگھی کرتے تھے۔","",{"t":"سر اور داڑھی میں کنگھی کرنا","k":"إسناده ضعیف: شعب الایمان، ح: 6046۔ محمد بن ہارون ضعیف ہے۔"}],[619,"سیدنا ابن عمر رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ نے فرمایا: \"رضاعت طبیعت کو بدل دیتی ہے۔\"","",{"t":"رضاعت کا طبیعت پر اثر","k":"إسناده ضعیف جدا: الضعیفة، ح: 3659۔ مسلمہ بن علی متروک اور محمد بن ہارون ضعیف ہے۔"}],[620,"مالک بن اوس بن حدثان کہتے ہیں: عمر رضی اللہ عنہ نے میری طرف پیغام بھیجا تو میں ان کی خدمت میں حاضر ہوا۔ انہوں نے کہا: پھر ابو بکر نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کا جانشین ہوں۔ تم دونوں یعنی عباس اور علی بھیجے گئے ہو... اور یہ حدیث بیان کی۔ ابو بکر نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہمارا ترکہ تقسیم نہیں ہوتا ہم جو کچھ چھوڑ جائیں وہ صدقہ ہوتا ہے۔\"","",{"t":"انبیاء کی میراث","k":"صحیح البخاری، ح: 4033۔ صحیح مسلم، ح: 1757۔ سنن ابی داؤد، ح: 2963۔ سنن الترمذی، ح: 1610۔","f":"صحیح البخاری وغیرہ میں یہ حدیث بایں الفاظ مروی ہے: مالک بن اوس بن حدثان نصری بیان کرتے ہیں کہ عمر رضی اللہ عنہ نے انہیں بلایا تو اچانک آپ کے چوکیدار رفاعہ آئے اور کہا کہ عثمان بن عفان، عبد الرحمن بن عوف، زبیر بن عوام اور سعد بن ابی وقاص رضی اللہ عنہم اندر آنا چاہتے ہیں، کیا آپ کی طرف سے انہیں اجازت ہے؟ آپ نے فرمایا: انہیں اندر بلا لو۔ تھوڑی دیر بعد رفاعہ پھر آئے اور کہا کہ عباس اور علی رضی اللہ عنہما اجازت چاہتے ہیں، آیا انہیں اندر آنے کی اجازت ہے؟ آپ نے فرمایا: ہاں۔ جب یہ دونوں بزرگ اندر تشریف لے آئے اور سلام کہا تو عباس رضی اللہ عنہ نے کہا: امیر المومنین! میرے اور اس کے درمیان فیصلہ کر دیجیے اور وہ دونوں بزرگ اس جائیداد کے متعلق جھگڑ رہے تھے جو اللہ تعالی نے اپنے رسول صلی اللہ علیہ وسلم کو بنو نضیر کے مال سے بطور فی عطا فرمایا تھا۔ اس موقع پر علی اور عباس رضی اللہ عنہما نے ایک دوسرے کو سخت سست کہا: (جب انہوں نے ایک دوسرے پر تنقید کی) تو حاضرین بولے: امیر المومنین! آپ ان دونوں کا فیصلہ کر دیں تاکہ ان دونوں میں کوئی جھگڑا نہ رہے۔ عمر رضی اللہ عنہ نے فرمایا: ذرا صبر کرو! میں آپ لوگوں سے اس اللہ کا واسطہ دے کر پوچھتا ہوں جس کے حکم سے زمین و آسمان قائم ہیں، کیا آپ کو معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا: 'ہم انبیاء کی جائیداد تقسیم نہیں ہوتی۔ ہم جو کچھ چھوڑ جائیں وہ صدقہ ہوتا ہے۔' اور اس سے رسول اللہ صلی اللہ علیہ وسلم کی مراد خود اپنی ذات تھی؟ حاضرین نے کہا: یقینا آپ صلی اللہ علیہ وسلم نے یہ فرمایا تھا۔ پھر عمر رضی اللہ عنہ عباس اور علی رضی اللہ عنہما کی طرف متوجہ ہوئے اور ان سے فرمایا: میں آپ دونوں کو اللہ کی قسم دے کر پوچھتا ہوں، کیا آپ کو بھی معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ حدیث بیان فرمائی تھی؟ ان دونوں بزرگوں نے بھی ہاں میں جواب دیا۔ اس کے بعد عمر رضی اللہ عنہ نے فرمایا: اب میں آپ لوگوں سے اس معاملے کے متعلق گفتگو کرتا ہوں۔ اللہ تعالی نے اپنے رسول صلی اللہ علیہ وسلم کو اس مال میں سے خاص طور پر عطا فرما دیا تھا، جو آپ کے سوا اور کسی کو نہیں دیا۔ ارشاد باری تعالی ہے: 'اللہ تعالی نے بنو نضیر کے اموال میں سے جو کچھ اپنے رسول کو دیا ہے تم نے اس کے لیے کوئی گھوڑے یا اونٹ نہیں دوڑائے۔' (یعنی تم نے کوئی جنگ وغیرہ نہیں کی) تو یہ مال خاص رسول اللہ صلی اللہ علیہ وسلم کے لیے تھا لیکن اللہ کی قسم! رسول اللہ صلی اللہ علیہ وسلم نے تمہیں نظر انداز کر کے اسے اپنے لیے مخصوص نہیں فرمایا اور نہ تم پر اپنی ذات ہی کو ترجیح دی تھی۔ آپ نے وہ مال تمہیں دیا اور تم پر تقسیم کر دیا حتی کہ اس میں سے صرف یہ مال باقی رہا ہے جو رسول اللہ صلی اللہ علیہ وسلم اپنے اہل و عیال پر سال بھر خرچ کرتے تھے اور جو مال باقی بچتا تھا، اسے آپ اللہ تعالی کے مصارف میں خرچ کیا کرتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم کا زندگی بھر یہی معمول رہا۔ پھر جب نبی صلی اللہ علیہ وسلم کی وفات ہو گئی تو ابو بکر رضی اللہ عنہ نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کا جانشین ہوں اور اس مال کو انہوں نے اپنے قبضے میں کر لیا اور اسے انہی مصارف میں خرچ کرتے رہے جن میں رسول اللہ صلی اللہ علیہ وسلم خرچ کیا کرتے تھے اور آپ لوگ یہیں موجود تھے۔ اس کے بعد عمر رضی اللہ عنہ اور عباس رضی اللہ عنہما کی طرف متوجہ ہوئے اور فرمایا: آپ لوگوں کو معلوم ہے کہ ابو بکر رضی اللہ عنہ نے وہی طریقہ اختیار کیا جیسا کہ آپ لوگوں کو بھی اس کا اقرار ہے۔ اللہ کی قسم! وہ اپنے طرز عمل میں سے، صحیح راستے پر اور حق کی پیروی کرنے والے تھے۔ پھر اللہ تعالی نے ابو بکر رضی اللہ عنہ کو بھی اٹھا لیا تو میں نے کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم اور ابو بکر رضی اللہ عنہما کا جانشین ہوں اور اپنی امارت کے دو سال تک اس پر قابض رہا اور اسے انہی مصارف میں خرچ کرتا رہا جن میں رسول اللہ صلی اللہ علیہ وسلم اور ابو بکر رضی اللہ عنہما نے کیا تھا۔ اور اللہ جانتا ہے کہ میں بھی اپنے طرز عمل میں سچا، صحیح راستے پر گامزن اور حق کی پیروی کرنے والا تھا۔ پھر آپ دونوں میرے پاس آئے۔ آپ دونوں ایک ہیں اور آپ کا معاملہ بھی ایک ہے۔ اے عباس! تم میرے پاس آئے تو میں نے تم دونوں سے کہا کہ رسول اللہ صلی اللہ علیہ وسلم کا ارشاد گرامی ہے: 'ہمارا ترکہ تقسیم نہیں ہوتا۔ ہم جو کچھ چھوڑ جائیں وہ صدقہ ہے۔' پھر میں نے سوچا کہ وہ جائیداد تمہارے حوالے کر دوں تو میں نے تمہیں کہا: اگر تم چاہتے ہو تو میں یہ جائیداد اس شرط پر تمہارے حوالے کرتا ہوں کہ تم اللہ تعالی کے سامنے کیے ہوئے تمام عہد کی ذمہ داریوں کو پورا کرو گے اور اس میں وہی طرز عمل اختیار کرو گے جو رسول اللہ صلی اللہ علیہ وسلم اور ابو بکر رضی اللہ عنہما نے کیا تھا اور جیسا آغاز خلافت سے میرا ہے۔ اگر تم ایسا نہیں کرو گے تو مجھ سے اس کے متعلق گفتگو نہ کرو۔ اس وقت تم نے کہا: اس شرط پر جائیداد ہمارے حوالے کر دو تو میں نے اسے تمہارے سپرد کر دیا۔ کیا اب تم مجھ سے اس کے سوا کوئی اور فیصلہ طلب کرتے ہو؟ اللہ کی قسم! جس کے حکم سے زمین و آسمان قائم ہیں میں تا قیامت اس کے علاوہ اور کوئی فیصلہ نہیں کر سکتا اگر تم ان شرائط کو پورا کرنے سے عاجز ہو تو جائیداد مجھے واپس کر دو۔ میں خود اس کا انتظام کر لوں گا۔ (صحیح البخاری، ح: ۴۰۳۳)\nانبیاء کی میراث کی تقسیم کے حوالے سے دیکھیے حدیث نمبر ۲۶۹ کے فوائد۔"}],[621,"محمد بن یزید بن طیفور۔ رحبہ طیفور والے نے ہمیں ۲۶۵ھ میں بیان کیا اور میں نے اس سال ان سے سنا جبکہ ان سے ان کی عمر کے بارے میں سوال کیا گیا تو انہوں نے کہا: میری ولادت ہارون کے خلیفہ بننے کے ایک سال اور چند ماہ بعد ۷۲ھ (یعنی ۱۷۲ھ) میں ہوئی، شعبان کے دس دن باقی تھے۔ میں نے ہشیم بن بشیر کو دیکھا اس وقت میں بچہ تھا، وہ میرے والد کے ہاں سے نکلے تھے، انہوں نے ان کے پاس کھانا کھایا تھا، میں نے انہیں دیکھا وہ گدھے پر سوار تھے اور ہمارے ہمسایوں اور ہمارے معلم نے انہیں گھیرا ہوا تھا۔ وہ رنگی ہوئی بڑی ڈاڑھی والے تھے، ان کے چہرے پر چیچک کے نشان تھے، بڑے ناک اور گندمی رنگت والے تھے، اس سال ان کی عمر ۹۵ برس تھی، ہم نے ان (ابن طیفور) سے یہ کلام آٹھ جمادی الآخرہ ۶۵ھ (یعنی ۲۶۵ھ) میں بدھ کے دن سماعت کیا جبکہ وہ عباس الدوری کی مجلس سے لوٹے تھے۔","",{"t":"محمد بن یزید بن طیفور","k":"إسناده ضعیف: تاریخ مدینة السلام: (601/4)،(602)۔ محمد بن یزید بن طیفور کی توثیق نہیں ملی۔"}],[622,"سیدنا ابن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نذر کے جانور میں کانا، لاغر، خارش زدہ اور جس کے تھن مکمل طور پر کاٹ دیے گئے ہوں، جائز نہیں ہیں۔\" علی بن عاصم نے کہا: عطاء یہی فتوی دیا کرتے تھے لیکن اسے مرفوع بیان نہیں کرتے تھے۔","",{"t":"نذر میں کون سے جانور جائز نہیں","k":"إسناده ضعیف: المعجم الاوسط، ح: 3578 (وفیہ لا یجوز فی البدن)۔ علی بن عاصم الواسطی ضعیف ہے۔"}],[623,"سیدنا سمرہ بن جندب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کا کوئی مال ضائع ہو جائے یا اس کا مال چوری ہو جائے پھر وہ اسی طرح اسے کسی شخص کے ہاتھ میں پائے تو وہ اس کا زیادہ حق دار ہے اور خریدار قیمت کے سلسلے میں بیچنے والے کی طرف رجوع کرے (اور قیمت واپس لے)۔\"","",{"t":"جس کی کوئی چیز چوری ہو جائے اور پھر وہ کسی کے پاس سے ملے","k":"إسناده ضعیف: سنن ابن ماجہ، ح: 2331۔ مسند احمد (13/5)۔ المصنف لابن ابی شیبة، ح: 23226۔ الضعیفة، ح: 1627۔ حجاج بن ارطاة ضعیف ہے۔"}],[624,"سیدنا اسامہ بن زید رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس امیمہ بنت زینب کو لایا گیا جبکہ (ان کی جان لرز رہی تھی) گویا وہ پرانے مشکیزے میں ہو، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: للہ ما اخذ وللہ ما اعطی وکل الی اجل مسمی (اللہ ہی کا تھا جو اس نے لیا اور اللہ ہی کا تھا جو اس نے دیا اور سب کچھ ایک وقت مقرر تک ہے)۔ راوی کہتا ہے: پھر آپ رو پڑے تو سعد بن عبادہ رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم سے کہا: اے اللہ کے رسول! آپ رو رہے ہیں جبکہ رونے سے آپ نے منع کیا ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ تو رحمت ہے جسے اللہ نے اپنے بندوں کے دلوں میں رکھا ہے اور اللہ اپنے بندوں میں سے رحم کرنے والوں ہی پر رحم کرتا ہے۔\"","",{"t":"میت پر رونے کی رخصت","k":"صحیح البخاری، ح: 1284۔ صحیح مسلم، ح: 923۔ سنن ابی داؤد، ح: 3125۔ سنن النسائی، ح: 1869۔ سنن ابن ماجہ، ح: 1588۔","f":"بعض روایتوں میں ہے کہ قریب المرگ سیدہ زینب کا بیٹا تھا، بعض میں بیٹا یا بیٹی تردد کے ساتھ ہے لیکن صحیح بات یہ ہے کہ وہ بیٹی تھی بیٹا نہیں تھا جیسا کہ مولف کی سند میں ہے۔\nحافظ ابن حجر رحمہ اللہ فرماتے ہیں کہ علماء انساب کا اتفاق ہے کہ سیدہ زینب کے بطن سے دو ہی بچے تھے ایک علی اور دوسری امامہ یا امیمہ۔ یہاں اشکال ہے کہ امامہ تو رسول اللہ صلی اللہ علیہ وسلم کے بعد زندہ رہی ہیں یہاں تک کہ سیدہ فاطمہ کے بعد سیدنا علی کے نکاح میں آئی ہیں جیسا کہ علماء تاریخ کا اتفاق ہے۔ تو اس اشکال کا جواب یہ ہے کہ سیدہ زینب نے جب رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں پیغام بھیجا تو اس وقت وہ بچی حالت نزاع میں تھی لیکن بعد ازاں اللہ تعالی نے اس بچی کو کامل صحت عطا فرما دی تھی اور وہ طویل عرصے تک زندہ رہی۔ بقول حافظ ابن حجر کہ اس عجیب و غریب واقع کو رسول اللہ صلی اللہ علیہ وسلم کے معجزات میں بیان کرنا چاہیے۔ (فتح الباری: (۱۹۹/۳)،(۲۰۱)۔ نیز دیکھیے: ہدایة القاری: (۷۸/۳)،(۷۹))\nقریب المرگ شخص کے لیے اصحاب علم و فضل لوگوں سے اس کے پاس آنے کی درخواست کرنا یا اسے ان کے پاس لے جانا تاکہ وہ اس کے لیے دعا کریں۔\nمیت کے گھر والوں کو صبر اور حوصلے کی تلقین کرنی چاہیے۔\nلوگوں میں اگر کسی کو کوئی اشکال پیدا ہو تو اسے چاہیے کہ اہل علم سے پوچھیں اور اہل علم کو چاہیے کہ کتاب و سنت کی روشنی میں اشکال رفع کریں۔\nمیت پر نوحہ کے بغیر رونے میں کوئی حرج نہیں۔\nاللہ کی مخلوق پر رحم و شفقت کا معاملہ کرنا چاہیے۔"}],[625,"سیدنا انس بن مالک رضی اللہ عنہ سیدہ ام سلیم رضی اللہ عنہا سے روایت کرتے ہیں کہ ان کا ایک بیٹا تھا اور اس (بیٹے) کی ایک نغیر (چڑیا) تھی رسول اللہ صلی اللہ علیہ وسلم ان کے ہاں تشریف لے جاتے اور اس (بچے) سے مزاح فرماتے۔ (ایک دن) آپ ان کے ہاں تشریف لے گئے تو اس (بچے) کو غمگین دیکھا تو آپ نے فرمایا: \"ابو عمیر کو کیا ہوا ہے؟\" انہوں نے کہا: اے اللہ کے رسول! اس کی نغیر (چڑیا) مر گئی ہے۔ یہ سن کر آپ فرمانے لگے: \"اے ابو عمیر! نغیر (چڑیا) نے کیا کیا۔\"","",{"t":"بچوں کے ساتھ مزاح کرنا","k":"صحیح البخاری، ح: 6203۔ صحیح مسلم، ح: 2150۔ سنن ابی داؤد، ح: 4969۔ سنن الترمذی، ح: 333۔ سنن ابن ماجہ، ح: 3720۔","f":"بچوں کے ساتھ ہنسی مزاح اور دل لگی کی باتیں کرنا جائز ہے جس سے بچوں کو خوشی ہو۔\nچھوٹے بچے کی کنیت رکھنا اور کنیت سے اسے پکارنا جائز ہے۔\nگھر میں پرندہ رکھنا جائز ہے بشرط یہ کہ اس کی خوراک کا مناسب خیال رکھا جائے۔"}],[626,"سیدنا انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمارے لیے مونچھیں کاٹنے، ناخن ترشوانے اور زیر ناف بال صاف کرنے کے لیے وقت مقرر کیا کہ ہم چالیس دن سے زیادہ نہ چھوڑیں۔","",{"t":"مونچھیں کاٹنے، ناخن ترشوانے اور زیر ناف بال صاف کرنے کی مدت","k":"صحیح مسلم، ح: 258۔ سنن ابی داؤد، ح: 4200۔ سنن الترمذی، ح: 2758۔ سنن النسائی، ح: 14۔ سنن ابن ماجہ، ح: 295۔","f":"مونچھیں کاٹنے، ناخن ترشوانے اور زیر ناف بال صاف کرنے کی مدت چالیس دن ہے، چالیس دن سے پہلے جب مناسب لگے ان کو کاٹ لے لیکن چالیس دن سے اوپر نہ ہو۔"}],[627,"سیدنا ابن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارا رب عزوجل فرماتا ہے کہ جب میرا بندہ اکیلے میں مجھے یاد کرتا ہے تو میں بھی اکیلے میں اسے یاد کرتا ہوں اور جب وہ کسی جماعت میں مجھے یاد کرتا ہے تو میں ان سے بہتر جماعت میں اسے یاد کرتا ہوں۔\"","",{"t":"یاد الہی کی فضیلت","k":"إسناده ضعیف: علی بن عاصم الواسطی ضعیف ہے۔ مسند البزار، ح: 5138۔ المعجم الکبیر، ح: 12484 میں فضیل بن سلیمان ضعیف ہے۔ صحیح البخاری کی حدیث (7405 عن ابی ہریرة رضی اللہ عنہ) اس سے بے نیاز کر دیتی ہے۔"}],[628,"سیدنا ابن عباس رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم عید کے دن عیدگاہ کی طرف نکلے آپ نے نماز (عید) سے پہلے کوئی نماز پڑھی اور نہ ہی اس کے بعد (کوئی نفلی نماز پڑھی)۔","",{"t":"نماز عید سے پہلے اور بعد کوئی نفل نہیں","k":"صحیح البخاری، ح: 964۔ صحیح مسلم، ح: 884۔ سنن ابی داؤد، ح: 1159۔","f":"نماز عید عیدگاہ میں ادا کرنا مسنون ہے تاہم کسی شرعی عذر کی صورت میں اسے مسجد میں بھی ادا کیا جا سکتا ہے۔\nنماز عید کی صرف دو رکعتیں ہیں ان سے پہلے یا بعد میں کوئی نفلی نماز نہیں۔"}],[629,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک نبی کسی درخت کے نیچے اترا تو اسے ایک چیونٹی نے کاٹ لیا تو انہوں نے اپنا سامان منتقل کرنے کا حکم دیا اور اس درخت کے متعلق حکم فرمایا تو اسے چیونٹیوں پر جلا دیا گیا، تب اللہ نے ان کی طرف وحی فرمائی کہ کیا (آپ کو کاٹنے والی) ایک ہی چیونٹی نہیں تھی؟ (مگر) آپ نے تو ایک ایسی امت مار ڈالی جو تسبیح کرتی تھی۔\"","",{"t":"چیونٹیوں کو مارنے کی ممانعت","k":"صحیح البخاری، ح: 3319۔ صحیح مسلم، ح: 2241۔ سنن ابی داؤد، ح: 5265۔ سنن النسائی، ح: 4363۔ سنن ابن ماجہ، ح: 3225۔","f":"چیونٹیوں کو بلاوجہ مارنا منع ہے، ہاں! اگر کوئی چیونٹی تکلیف پہنچائے تو صرف تکلیف پہنچانے والی چیونٹی کو مارا جا سکتا ہے۔\nچیونٹیاں بھی اللہ تعالی کی تسبیح کرتی ہیں۔"}],[630,"عبد الرحمن بن ابی لیلی بیان کرتے ہیں کہ علی رضی اللہ عنہ (نماز میں) بسم اللہ الرحمن الرحیم جہرا پڑھا کرتے تھے۔","",{"t":"نماز میں بسم اللہ جہرا پڑھنا","k":"إسناده ضعیف: الخلافیات للبیہقی، ح: 1595۔ ابو سعد الاعور سعید بن مرزبان ضعیف ہے۔ حدیث نمبر 441 اس سے بے نیاز کر دیتی ہے۔"}],[631,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم بنو نجار کے نخلستان سے گزرے آپ نے کچھ لوگوں کی آوازیں سنی جنہیں ان کی قبروں میں عذاب ہو رہا تھا تو آپ نے فرمایا: \"اگر اس بات کا ڈر نہ ہوتا کہ تم (مردے) دفنانا چھوڑ دو گے تو میں ضرور اللہ سے دعا کرتا کہ وہ تمہیں بھی ان کی آوازیں سنا دے۔\"","",{"t":"عذاب قبر","k":"صحیح: دیکھیے: حدیث نمبر 34۔"}],[632,"مالک بن انس رضی اللہ عنہ سے مروی ہے کہ انہوں نے ابن شہاب رحمہ اللہ سے موزوں پر مسح کے متعلق دریافت کیا تو ابن شہاب نے کہا: اس سلسلے میں مسافر اور مقیم کے لیے وقت کی تحدید ہم تک نہیں پہنچی۔","",{"t":"مسافر اور مقیم کے مسح کی مدت","k":"إسناده ضعیف: خالد بن اسماعیل الکذوی اور محمد بن یزید کی توثیق نہیں ملی۔"}],[633,"عامر فرماتے ہیں کہ مجھے اس شخص نے خبر دی جس نے علی رضی اللہ عنہ کے ساتھ نماز جنازہ پڑھی کہ آپ رضی اللہ عنہ نے چھ تکبیریں کہیں۔","",{"t":"نماز جنازہ میں تکبیرات","k":"إسناده ضعیف جدا: اسماعیل بن ابان متروک، محمد بن یزید کی توثیق مطلوب ہے جبکہ عامر شعی کو خبر دینے والا نامعلوم ہے۔"}],[634,"سیدنا ابن عباس رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ نے قبروں کی زیارت کرنے والی عورتوں اور ان پر سجدے کرنے اور دیے چلانے والی عورتوں پر لعنت کی ہے۔","",{"t":"عورتوں کا قبرستان جانا","k":"إسناده ضعیف: سنن ابی داؤد، ح: 3236۔ سنن الترمذی، ح: 320۔ سنن النسائی، ح: 2045۔ سنن ابن ماجہ، ح: 1575۔ ابو صالح باذام ضعیف ہے۔ سنن الترمذی کی حدیث (1056 وسندہ حسن) اس سے بے نیاز کر دیتی ہے۔"}],[635,"اشعث حسن بصری سے ایک ایسے آدمی کے بارے میں روایت کرتے ہیں جس نے ایسی مچھلی کا شکار کیا کہ اس (مچھلی) کے پیٹ میں ایک مچھلی تھی۔ انہوں (حسن بصری) نے فرمایا: وہ ان سب کو کھا سکتا ہے۔ ابن طیفور کہتے ہیں: بلاشبہ یہ بھی رزق کی پاکیزگی میں سے ہے۔","",{"t":"مچھلی کا شکار","k":"إسناده ضعیف: اشعث بن سوار ضعیف اور ابن طیفور کی توثیق نہیں ملی۔"}],[636,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: زیور پہننے میں کوئی حرج نہیں جب اس کی زکوۃ ادا کر دی جائے۔","",{"t":"زیورات کی زکوۃ","k":"حسن: السنن الکبری للبیہقی، ح: 7545۔ سنن الدارقطنی، ح: 1938۔ الاموال لابی عبید، ح: 1265۔","f":"زیورات جب نصاب کے مطابق ہوں تو ان میں زکوۃ کے وجوب کے بارے میں اگرچہ اہل علم کا اختلاف ہے لیکن صحیح بات یہی ہے کہ زیورات میں بھی زکوۃ واجب ہے بشرط یہ کہ وہ نصاب کے مطابق ہوں خواہ محض پہننے اور زیب و زینت کے لیے ہوں۔\nزیورات پر زکات کے سلسلے میں راقم کا تفصیلی مضمون ہے ملاحظہ فرمائیں: سونے اور چاندی کے زیورات کی زکوۃ کے بارے میں اہل علم کا سخت اختلاف ہے۔ سلف کی ایک جماعت عدم وجوب کی قائل ہے جب کہ دوسری جماعت کے نزدیک زکوۃ واجب ہے۔ امام ترمذی رحمہ اللہ (المتوفی: ۲۷۹ھ) فرماتے ہیں: \" واختلف أهل العلم في ذلك فرأى بعض أهل العلم من أصحاب النبي صلى الله عليه وسلم والتابعين في الحلي زكاة ما كان منه ذهب وفضة وبه يقول سفيان الثوري وعبد الله بن المبارك. وقال بعض أصحاب النبي صلى الله عليه وسلم منهم ابن عمر وعائشة وجابر بن عبد الله وأنس بن مالك: ليس في الحلي زكاة، وهكذا روي عن بعض فقهاء التابعين وبه يقول مالك بن أنس والشافعي وأحمد وإسحاق . “ اس مسئلہ میں اہل علم کا اختلاف ہے۔ صحابہ کرام رضی اللہ عنہم اور تابعین میں سے بعض اہل علم سونے اور چاندی کے زیورات میں زکوۃ کے قائل ہیں۔ سفیان ثوری اور عبد اللہ بن مبارک بھی یہی کہتے ہیں اور بعض صحابہ کرام رضی اللہ عنہم جن میں سیدنا ابن عمر، عائشہ، جابر بن عبد اللہ اور انس بن مالک رضی اللہ عنہم شامل ہیں، کہتے ہیں کہ زیورات میں زکوۃ نہیں ہے۔ بعض فقہاء تابعین سے بھی یہی مروی ہے اور یہی امام مالک بن انس، شافعی ، احمد اور اسحاق بھی کہتے ہیں۔ (سنن الترمذی، تحت حدیث: ۶۳۶) اس مختلف فیہ مسئلہ میں ہماری رائے یہ ہے کہ زیورات اگر نصاب کو پہنچ جائیں تو ان میں زکوۃ واجب ہے۔ جیسا کہ ابن حزم اندلسی رحمہ اللہ (المتوفی: ۴۵۶ھ) فرماتے ہیں: والزكاة واجبة في حلي الفضة والذهب إذا بلغ كل واحد منهما المقدار الذي ذكرنا واتم عند مالكه عاما قمريا .“ سونے اور چاندی کے زیورات پر زکوۃ واجب ہے جب ان میں سے ہر ایک اس مقدار (نصاب) کو پہنچ جائے جو ہم بیان کر آئے ہیں اور اس کے مالک کے پاس ان پر ایک قمری سال پورا ہو جائے ۔ (المحلی: ۷۴۰/۳) . اور احتیاط بھی اسی میں ہے کہ زیورات کی زکوۃ ادا کی جائے۔ اس کے درج ذیل دلائل ہیں۔ وجوب کے دلائل: دلیل نمبر (۱) ... جناب عمرو بن شعیب اپنے والد سے اور وہ (شعیب) اپنے دادا (عبد اللہ بن عمرو رضی اللہ عنہ) سے روایت کرتے ہیں: أَنَّ امْرَأَةٌ أَتَتْ رَسُولَ اللهِ صلى الله عليه وسلم وَمَعَهَا ابْنَةٌ لَهَا ، وَفِي يَدِ ابْنَتِهَا مَسَكَتَان غَلِيظَتَانِ مِنْ ذَهَبٍ، فَقَالَ لَهَا: ((أَتُعْطِينَ زَكَاةَ هَذَا؟ قَالَتْ : لا ، قَالَ: ((أَيَسُرُّكِ أَنَ يُسَوِّرَكِ اللَّهُ بِهِمَا يَوْمَ الْقِيَامَةِ سِوَارَيْنِ مِنْ نَارٍ؟ قَالَ: فَخَلَعَتْهُمَا فَأَلْقَتْهُمَا إِلَى النَّبِيِّ صلى الله عليه وسلم وَقَالَتْ: هُمَا لِلَّهِ وَلِرَسُولِهِ . ایک خاتون رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آئی، اس کے ساتھ اس کی ایک بیٹی تھی اور بیٹی کے ہاتھ میں سونے کے دو موٹے کنگن تھے۔ آپ صلی اللہ علیہ وسلم نے اس خاتون سے پوچھا: \"کیا تم اس کی زکوۃ دیتی ہو؟“ اس نے کہا: نہیں۔ آپ نے فرمایا: \"کیا تجھے یہ بات اچھی لگتی ہے کہ روز قیامت اللہ تجھے ان کے بدلے آگ کے دو کنگن پہنا ہے ؟ یہ سن کر اس عورت نے ان کو اتارا اور نبی صلی اللہ علیہ وسلم کے سامنے ڈال دیا اور کہنے لگی: یہ اللہ اور اس کے رسول کے لیے ہیں ۔ (سنن ابی داؤد، ح: ۱۵۶۳) اس کی سند حسن ہے۔ اسے علامہ نووی نے ”هذا إسناد حسن“ ابن القطان الفاسی نے ”إسناد صحيح إلى عمرو بن شعیب” ابن حجر نے ”إسناده قوي“ اور ابن ملقن نے ”صحیح“ کہا ہے۔ دیکھیے: المجموع: ۳۳/۶۔ بیان الوہم: ۳۶۶/۵۔ بلوغ المرام: (۶۰۶)،(۶۰۷)۔ البدر المنیر: ۵۶۵/۵ امام ابوداؤد نے اس حدیث پر یوں باب باندھا: \"باب الكنز ما هو؟ وزكاة الحلي\" \"کنز کیا ہے؟ اور زیورات کی زکوۃ کا بیان۔ امام نسائی یوں تبویب فرماتے ہیں: \"زكوة الحلي” زیورات کی زکوۃ کا بیان۔“ (سنن النسائي، قبل حديث : ۲۴۸۱) امام بیہقی فرماتے ہیں: ”باب سياق أخبار وردت في زكاة الحلي“ ” ان احادیث کا بیان جو زیورات کی زکوۃ کے سلسلے میں وارد ہوئی ہیں ۔ (السنن الکبری ، کتاب الزكاة، رقم الباب: ۷۱) امام منذری بھی اس حدیث کو “فصل في زكاة الحلي” میں لائے ہیں۔ الترغیب والترہیب : ۶۰۲/۱) آئمہ کرام کی یہ تبویب اس بات کی طرف اشارہ کرتی ہے کہ زیورات میں زکوۃ واجب ہے اور یہ حدیث مسئلہ ہذا میں نص کی حیثیت رکھتی ہے۔ اعتراض نمبر (۱) عمرو بن شعيب عن أبيه عن جده (عمرو بن شعیب اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں) یہ سند مرسل ہے یا منقطع ہے۔ کیوں کہ اگر “عن جدہ“ کی ضمیر کا مرجع عمرو بن شعیب ہو تو اس سے مراد عمرو کا دادا محمد بن عبد اللہ ہوگا اس صورت میں یہ روایت مرسل ہوگی کیوں کہ محمد بن عبد اللہ صحابی نہیں۔ اور اگر ضمیر کا مرجع شعیب ہو تو اس سے مراد سیدنا عبد اللہ بن عمرو ہیں۔ اس صورت میں یہ روایت منقطع ہوگی کیوں کہ شعیب کا اپنے دادا عبد اللہ سے سماع ثابت نہیں ہے۔ جواب..... یہ سند مرسل ہے نہ منقطع، بلکہ متصل اور حسن درجے کی ہے، کیوں کہ : جدہ کی ضمیر کا مرجع شعیب ہے۔ یعنی جد سے مراد شعیب کے دادا عبد اللہ بن عمرو ہیں نہ کہ عمرو بن شعیب کے دادا محمد بن عبد اللہ ۔ عبد اللہ بن عمرو رضی اللہ صحابی ہیں لہذا ارسال کا شبہ زائل ہوا۔ امام ذہبی رحمہ اللہ: (المتوفی: ۷۴۸ھ) فرماتے ہیں: \"فاذا قال: عن أبيه ، ثم قال: عن جده فإنما يريد بالضمير في جده أنه عائد إلى شعيب“ ” جب وہ (عمرو) عن أبيه“ کہے، پھر عن جده کہے تو بلاشبہ جدہ کی ضمیر کا شعیب کی طرف لوٹنا مراد ہے۔(ميزان الإعتدال : ۲۶۶/۳) علامہ علائی (المتوفی ۷۶۱ھ) فرماتے ہیں: \" و الضمير المتصل بجده في قولهم عمرو بن شعيب عن أبيه عن جده عائد إلى شعیب لا إلى عمرو وقد بينت ذلك وبسطت الكلام عليه في غير هذا الكتاب . “ عمرو بن شعیب عن ابیہ عن جدہ میں جدہ کی ضمیر متصل شعیب کی طرف لوٹتی ہے ، عمرو کی طرف نہیں۔ اور میں یہ بات اپنی دوسری کتابوں میں تفصیل سے بیان کر چکا ہوں ۔“ (جامع التحصیل : ۱۹۶) حافظ ابن کثیر رحمہ اللہ (المتوفی: ۷۷۴ھ) فرماتے ہیں: رہی بیٹے کی اپنے باپ سے، اس کی دادا سے روایت، تو یہ بھی زیادہ ہے مگر پہلی قسم سے کم ہے۔ جیسے: \"عمرو بن شعیب بن محمد بن عبد الله بن عمرو عن أبيه شعيب عن جده عبد الله بن عمرو بن العاص والی سند ( یاد رہے کہ اس سند کی تشریح) یہی صحیح ہے، اس کے علاوہ دوسری کوئی بات صحیح نہیں ہے۔“ (اختصار علوم الحديث، ص : ۱۳۳) ہمارے شیخ حافظ زبیر علی زئی رحمہ اللہ فرماتے ہیں: حافظ ابن کثیر کا مطلب یہ ہے کہ شعیب اپنے دادا عبد اللہ سے روایت بیان کرتے ہیں، اپنے والد محمد سے بیان نہیں کرتے ۔ (ایضاً) یہ سند منقطع اس لیے نہیں کہ شعیب کا اپنے دادا عبد اللہ بن عمرو سے سماع ثابت ہے۔ عمرو بن شعیب اپنے والد (شعیب) سے روایت کرتے ہیں کہ ایک آدمی عبد اللہ بن عمرو رضی اللہ عنہ کے پاس آیا اور ان سے ایک ایسے شخص کے متعلق پوچھنے لگا جس نے حالت احرام میں اپنی بیوی سے صحبت کر لی۔ عبد اللہ بن عمرو رضی اللہ عنہ نے عبد اللہ بن عمر رضی اللہ عنہ کی طرف اشارہ کرتے ہوئے کہا کہ جا کر ان سے یہ مسئلہ دریافت کرو۔ شعیب کہتے ہیں کہ وہ شخص انھیں نہیں جانتا تھا لہذا میں اس کے ساتھ گیا تو اس نے ابن عمر رضی اللہ عنہ سے وہی مسئلہ پوچھا تو انھوں نے فرمایا کہ تیرا حج باطل ہے۔ وہ آدمی کہنے لگا: اب میں کیا کروں؟ انھوں نے فرمایا: لوگوں کے ساتھ نکلو اور ویسا ہی کرو جیسا لوگ کر رہے ہیں، جب آئندہ سال ہو تو حج اور قربانی کرنا۔ اس کے بعد وہ شخص عبد اللہ بن عمرو کے پاس واپس آیا میں بھی اس کے ساتھ تھا۔ اس نے انھیں اس کی خبر دی۔ پھر عبد اللہ بن عمرو نے اسے ابن عباس رضی اللہ عنہ کی طرف بھیجا کہ ان سے بھی جا کر دریافت کرو۔ شعیب کہتے ہیں کہ پھر میں اس کے ساتھ ابن عباس رضی اللہ عنہ کے پاس گیا۔ اس نے ان سے بھی پوچھا تو انھوں نے بھی ابن عمر رضی اللہ عنہ کی طرح جواب دیا پھر وہ دوبارہ عبداللہ بن عمرو کے پاس آیا میں بھی اس کے ساتھ تھا تو اس نے انھیں ابن عباس رضی اللہ عنہ کے جواب سے بھی مطلع کیا۔ پھر اس نے کہا: آپ اس کے بارے میں کیا کہتے ہیں؟ تو عبد اللہ بن عمرو نے فرمایا: جو ان دونوں نے کہا وہی میں کہتا ہوں ۔ (السنن الكبرى للبيهقي، ح: ۹۷۸۳، واسناده صحيح) امام بیہقی یہ حدیث بیان کر کے فرماتے ہیں : \"هذا إسناد صحيح وفيه دليل على صحة سماع شعيب بن محمد بن عبد الله من جده عبد الله بن عمرو” “یہ سند صحیح ہے اور اس میں اس بات کی بھی دلیل ہے کہ شعیب بن محمد بن عبد اللہ کا اپنے دادا عبد اللہ بن عمرو سے سماع صحیح ہے۔” (ایضاً) امام حاکم (المتوفی : ۴۰۵ھ ) فرماتے ہیں: كنت أطلب الحجة الظاهرة في سماع شعیب بن محمد بن عبد الله بن عمرو، فلم أصل إليها إلى هذا الوقت . میں مسلسل اسی دلیل کی تلاش میں رہا جو شعیب بن محمد کے عبد اللہ بن عمرو سے سماع پر بین دلیل ہو لیکن ابھی تک مجھے ایسی کوئی دلیل نہیں ملی۔\" پھر امام موصوف نے یہی حدیث بیان کی اور فرمایا: هذا حديث ثقات رواته حفاظ، وهو كالآخذ باليد في صحة سماع شعيب بن محمد عن جده عبد الله بن عمرو \"اس حدیث کے تمام راوی ثقہ ہیں، حفاظ ہیں اور یہ حدیث شعیب بن محمد کے ان کے دادا عبد اللہ بن عمرو سے سماع کے ثبوت پر بڑی مضبوط دلیل ہے۔ (المستدرک: ۶۵/۲) امام بخاری رحمہ اللہ (المتوفی : ۲۵۶ھ) فرماتے ہیں: \" وقد سمع شعيب بن محمد من جده عبد الله بن عمرو شعیب بن محمد نے اپنے دادا عبد اللہ بن عمرو سے سماع کیا ہے۔“ (جامع الترمذي، تحت رقم الحديث: ۳۲۲) امام دارقطنی کے استاد ابوبکر عبد اللہ بن محمد النیسابوری (المتوفی : ۳۲۴ھ) فرماتے ہیں: ”نا محمد بن على الوراق، قال: قلت لأحمد بن حنبل عمرو بن شعیب سمع من أبيه شيئًا ؟ قال : يقول : حدثني أبي، قال: قلت: فأبوه سمع من عبد الله بن عمرو؟ قال: نعم، أراه قد سمع منه . “ ہمیں محمد بن علی الوراق (ثقہ) نے بیان کیا، وہ کہتے ہیں کہ میں نے امام احمد بن حنبل سے پوچھا: کیا عمرو بن شعیب نے اپنے والد سے کچھ سنا ہے؟ انھوں نے فرمایا: وہ تو “حدثنی أبی” ( مجھے میرے والد نے بیان کیا ) کہتا ہے۔ میں نے پوچھا: تو کیا اس کے والد (شعیب) نے عبد اللہ بن عمرو سے سنا ہے؟ انھوں نے فرمایا : ہاں، یقیناً اس نے اس سے سنا ہے۔“ امام دارقطنی فرماتے ہیں: \"سمعت أبا بكر النيسابورى، يقول: هو عمرو بن شعیب بن محمد بن عبد الله بن عمرو بن العاص، وقد صح سماع عمرو بن شعيب عن أبيه شعيب ، وصح سماع شعيب من جده عبد الله بن عمرو ” میں نے (اپنے استاد ) ابوبکر النیسابوری کو یہ فرماتے سنا: وہ عمرو بن شعیب بن محمد بن عبد اللہ بن عمرو بن العاص ہے، عمرو بن شعیب کا اپنے والد شعیب سے سماع صحیح ہے اور شعیب کا اپنے دادا عبد اللہ بن عمرو سے سماع صحیح ہے۔ (سنن الدارقطنی، ح: ۲۹۷۹) علامہ علائی (المتوفی : ۷۶۱ھ) فرماتے ہیں: والأصح أنه سمع من جده عبد الله بن عمرو .... اور صحیح ترین بات یہ ہے کہ اس (شعیب) نے اپنے دادا عبد اللہ بن عمرو سے سنا ہے۔” (جامع التحصيل، ص : ۱۹۶) علامہ ذہبی رحمہ اللہ (المتوفی : ۷۴۸ھ) فرماتے ہیں: “لأن شعيبا ثبت سماعه من عبد الله وهو الذي رباه حتى قيل إن محمدا مات في حياة أبيه عبد الله فكفل شعيبا جده عبد الله .“ شعیب کا عبد اللہ سے سماع ثابت ہے اور اسی (عبد اللہ ) نے اس (شعیب) کی پرورش کی تھی یہاں تک کہا گیا ہے کہ محمد (شعیب کا والد ) اپنے باپ عبد اللہ کی زندگی ہی میں فوت ہو گیا تو شعیب کے دادا عبد اللہ نے (اپنے پوتے) شعیب کی کفالت کی ۔ “ (میزان الاعتدال : ۲۶۶/۳) اور فرماتے ہیں: قلت قد مر أن محمدا قديم الموت وصح أيضا أن شعيبا سمع معاوية، وقد مات معاوية قبل عبد الله بن عمرو بسنوات، فلا ينكر له السماع من جده سيما وهو الذي رباه وكفله . “ \" میں کہتا ہوں کہ پہلے بیان ہو چکا ہے کہ محمد کا انتقال بہت پہلے ہو گیا تھا اور یہ بات مستند طور پر منقول ہے کہ شعیب نے معاویہ رضی اللہ عنہ سے بھی سماع کیا ہے اور معاویہ کا انتقال عبد اللہ بن عمرو کے انتقال سے کچھ سال پہلے ہوا تھا تو اس کا اپنے دادا سے سماع منکر شمار نہیں ہوگا بطور خاص اس صورت میں کہ جب اس کے دادا نے اس کی پرورش اور کفالت کی ہو۔ (میزان الاعتدال : ۲۶۷/۳) حافظ ابن حجر رحمہ اللہ (المتوفی : ۸۵۲ھ) فرماتے ہیں: \"صدوق، ثبت سماعه من جده صدوق ہے اس کا اپنے دادا سے سماع ثابت ہے۔“ (التقریب: ۲۸۰۶) علاوہ ازیں شعیب کے پاس اپنے دادا سیدنا عبد اللہ بن عمرو رضی اللہ عنہ کا لکھا ہوا صحیفہ بھی موجود تھا جس سے وہ روایت کرتے ہوئے بیان کرتے تھے۔ شعیب کے بعد یہ صحیفہ ان کے بیٹے عمرو بن شعیب کے پاس رہا۔ انھوں نے بھی اس سے بیان کیا “کما لا یخفی علی أہل العلم“۔ یاد رہے کہ کتاب سے بیان کرنا مناولہ، اجازہ اور یا پھر وجادہ کی قبیل سے ہے۔ قول راج میں ان تمام صورتوں میں روایت صحیح ہوتی ہے۔ (فتاویٰ علمیہ: ۳۰۸/۱) جمہور محدثین کے نزدیک عمرو بن شعیب عن أبيه عن جده والی سند صحیح، حسن اور حجت ہوتی ہے۔ امام بخاری رحمہ اللہ (المتوفی: ۲۵۶ھ) فرماتے ہیں: \"رأيت أحمد ابن حنبل وعلي بن والحميدي وإسحاق بن ابراهيم يحتجون بحديث عمرو بن شعيب عن أبيه“ میں نے امام احمد بن حنبل، علی بن عبد اللہ، حمیدی اور اسحاق بن ابراہیم کو دیکھا وہ سب عمرو بن شعیب عن ابیہ کی حدیث سے حجت پکڑتے تھے۔ (التاریخ الکبیر: ۳۴۲/۶-۳۴۳) امام اسحاق بن راہویہ (المتوفی : ۲۳۸ھ) فرماتے ہیں: \"إذا كان الراوي عن عمرو بن شعيب ثقة فهو كأيوب عن نافع عن ابن عمر” “جس وقت عمرو بن شعیب سے روایت کرنے والا ثقہ ہو تو یہ سند مثل ایوب عن نافع عن ابن عمر کے ہے۔ (المستدرک للحاکم : ۱۰۵/۱ وسنده صحيح) امام ترمذی رحمہ اللہ (المتوفی : ۲۷۹ھ) نے عمرو بن شعیب کی بہت سی حدیثوں کو “حسن صحیح” کہا ہے۔ سنن الترمذی، ح: (۱۱۸۱)،(۱۲۳۴)،(۱۵۸۵) وغیرہ ابن خزیمہ رحمہ اللہ (المتوفی : ۳۱۱ھ) نے اسے ”الصحیح“ میں ذکر کیا اور جرح نہیں کی لہذا ان کے نزدیک بھی یہ صحیح ہے۔ (دیکھیے: صحیح ابن خزیمہ، ح: ۱۷۴ وغیرہ) امام ابن الجارود (المتوفی : ۳۰۷ھ) نے ”المنتقی“ میں بیان کیا تو وہ ان کے نزدیک بھی صحیح ہوئی۔المنتقی، ح: (۱۹)،(۷۵) وغیرہ امام حاکم رحمہ اللہ (المتوفی : ۴۰۵ھ) فرماتے ہیں: \"هذا حديث صحيح الإسناد” (المستدرک: ۱۴/۲) علامہ منذری رحمہ اللہ (المتوفی : ۶۵۶ھ ) اس سند سے مروی ایک روایت بیان کر کے فرماتے ہیں: رواه الأصبهاني بإسناد حسن۔ (الترغیب والترہیب، ح: ۴۱۷۱) امام بغوی رحمہ اللہ (المتوفی : ۵۱۶ھ ) اس سند سے مروی حدیث کو ”هذا حديث حسن“ کہتے ہیں۔ (شرح السنۃ، ح: ۲۶۷۵) علامہ نووی نے (المتوفی : ۶۷۷ ھ ) اس سند سے مروی ایک حدیث کے متعلق فرماتے ہیں: \"رواه أبو داود والترمذى والنسائى بأسانيد صحيحة” (ریاض الصالحین : ۹۵۹) شیخ الاسلام ابن تیمیہ رحمہ اللہ (المتوفی : ۷۲۸ھ) فرماتے ہیں: \"وأما أئمة الإسلام وجمهور العلماء فيحتجون بحديث عمرو بن شعيب عن أبيه عن جده إذا صح النقل إليه“ رہے ائمہ اسلام اور جمہور علماء تو وہ سب عمرو بن شعیب عن ابیہ عن جدہ کی حدیث سے حجت پکڑتے ہیں جب وہ اس (عمرو) تک صحیح سند منقول ہو۔ (مجموع الفتاوی : ۸/۱۸) علامہ مزی رحمہ اللہ (المتوفی : ۷۴۲ھ) فرماتے ہیں: \"فدل ذلك على أن حديث عمرو بن شعيب عن ابيه عن جده صحيح متصل إذا صحيح الإسناد إليه، وأن من ادعى فيه خلاف ذلك فدعواه مردودة حتى يأتي عليها بدليل صحيح يعارض ما ذكرناه والله اعلم ”پس یہ چیز اس بات پر دلالت کرتی ہے کہ عمرو بن شعیب عن ابیہ عن جدہ والی حدیث صحیح ہے، متصل ہے بشرط یہ کہ اس (عمرو) تک سند صحیح ہو، اور جس نے اس سلسلے میں اس کے خلاف دعوی کیا ( یعنی یہ کہا کہ یہ ضعیف ہے ) تو اس کا دعوی مردود ہے تاوقت یہ کہ وہ اپنے اس دعوی پر ایسی صحیح دلیل لے کر آئے جو ہماری بات کے معارض ہو۔“ (تھذیب الکمال : ۶۰۸/۴)۔ حافظ ذہبی رحمہ اللہ (المتوفی: ۷۴۸ھ) فرماتے ہیں: \"لسنا نقول: إن حديثه من أعلى اقسام الصحيح بل هو من قبيل الحسن“ ہم یہ نہیں کہتے کہ اس کی نقل کردہ حدیث صحیح کی اعلیٰ اقسام سے تعلق رکھتی ہے بلکہ ہم کہتے ہیں کہ وہ حسن کی قسم سے تعلق رکھتی ہے۔ (میزان الاعتدال : ۲۶۸/۳) حافظ ابن القیم رحمہ اللہ (المتوفی : ۷۵۲ھ) فرماتے ہیں: ”و عمرو بن شعيب ثقة بإتفاق أئمة الحديث، قال: وإذا روى عن غير أبيه لم يختلف أحد في الإحتجاج به، وأما رواياته عن أبيه عن جده فالأكثرون على أنها متصلة ليس فيها إرسال ولا انقطاع . “ عمرو بن شعیب باتفاق ائمہ حدیث ثقہ ہے۔ جب وہ (عن ابیہ عن جدہ) کے علاوہ کسی سند سے بیان کرے تو اس سے حجت پکڑنے میں کسی کا اختلاف نہیں اور رہی اس کی وہ روایات جو عن ابیہ عن جدہ کی سند سے ہیں تو اکثریت کے ہاں یہ متصل ہے، اس میں ارسال اور انقطاع نہیں ہے۔“ (حاشیۃ ابن القیم علی مختصر سنن ابی داؤد: ۱۳۴/۱)۔ حافظ ابوالفضل عراقی رحمہ اللہ (المتوفی : ۸۲۶ ھ ) اس سند سے مروی حدیث کے متعلق فرماتے ہیں: \"إسنادہ حسن۔\" (المغنی عن حمل الاسفار، ح: ۶۴، الشاملہ) حافظ ابن حجر رحمہ اللہ (المتوفی : ۸۵۲ھ) فرماتے ہیں: \"إسناده قوي“ بلوغ المرام، ح: (۶۰۶)،(۶۰۷) اعتراض نمبر (۲): اس کی سند میں حسین بن ذکوان ہے جس کے بارے میں امام یحیی بن سعید اور عقیلی فرماتے ہیں کہ اس کی حدیث میں اضطراب پایا جاتا ہے۔ جواب: حسین بن ذکوان المعلم البصری صحیحین کے راوی ہیں جنھیں جمہور آئمہ کرام نے ثقہ و صدوق قرار دیا ہے۔ امام ذہبی فرماتے ہیں: \"الحسین المعلم هو الحافظ الحجة الحسين بن ذكوان المكتب العوذى مولاهم البصرى أحد الثقات، حدث عن ابن بريدة وعطاء بن أبي رباح وعمرو بن شعيب وقتادة ويحيى بن أبي كثير وعدة، روى عنه خلق كثير منهم إبراهيم بن طهمان وابن المبارك وعبد الوارث ويحيى القطان وغندر ويزيد بن زريع وروح بن عبادة، وثقه أبو حاتم والنسائي، أظنه توفي سنة بضع وأربعين ومائة وقد جاوز الستين وكان كبير القدر وافر العلم رحمہ اللہ علیہ۔\" حسین بن ذكوان المعلم المكتب العوذی البصری آپ حافظ حدیث اور حجت ہیں، ثقات میں سے ہیں۔ آپ نے ابن بریدہ، عطاء بن ابی رباح، عمرو بن شعیب، قتادہ، یحیی بن ابی کثیر اور متعدد اہل علم سے، جب کہ آپ سے خلق کثیر نے جن میں ابراہیم بن طہمان، ابن المبارک، عبد الوارث، یحیی القطان، غندر، یزید بن زریع اور روح بن عبادہ شامل ہیں، نے روایات نقل کی ہیں۔ امام ابو حاتم اور نسائی نے آپ کو ثقہ کہا ہے۔ میرا خیال ہے کہ آپ کی وفات ۱۴۰ھ سے چند سال بعد ہوئی۔ آپ نے ساٹھ سال سے زائد عمر پائی۔ آپ جلیل القدر اور کثیر العلم انسان تھے۔ (تذکرۃ الحفاظ: ۱۳۱/۱) اور فرماتے ہیں: أحد الثقات والعلماء: ضعفه العقيلي بلا حجة ، روى عن ابن بريدة وعطاء وطائفة وعنه ابن المبارك وشعبة ويحيى القطان وخلق وثقه ابن معين وأبو حاتم وقال يحيى القطان مرة فيه إضطراب وذكر العقيلي حديثا واحدا غيره يرسله، فكان ماذا ، فمن ذا الذي ما غلط في أحاديث أشعبة؟ أمالك؟\" \"آپ ثقہ اور اہل علم افراد میں سے ہیں۔ آپ نے ابن بریدہ، عطاء اور ایک جماعت سے اور آپ سے ابن مبارک، شعبہ، یحیی القطان اور خلق کثیر نے روایات نقل کی ہیں۔ امام عقیلی نے بغیر کسی دلیل کے آپ کو ضعیف قرار دے دیا۔ ابن معین اور ابو حاتم آپ کو ثقہ قرار دیتے ہیں۔ امام یحیی القطان نے کہا: آپ میں اضطراب پایا جاتا ہے اور عقیلی نے آپ کے حوالے سے ایک روایت ذکر کی ہے جسے (انھوں نے موصول بیان کیا ہے اور) ان کے علاوہ دیگر حفاظ نے اسے مرسل بیان کیا ہے۔ لیکن یہ کوئی ایسی بات نہیں۔ کیوں کہ کون شخص ایسا ہے جس سے روایت کرنے میں غلطی نہ ہو، کیا وہ شعبہ ہیں یا امام مالک؟ (ميزان الإعتدال : ۵۳۴/۱-۵۳۵) اور فرماتے ہیں: \"وثقہ أبو حاتم الرازي والنسائى والناس وقد ذكره العقيلي في كتاب الضعفاء له بلا مستند، وقال: هو مضطرب الحديث. وقال أبوبكر بن خلاد: سمعت يحيى بن سعيد القطان وذكر حسين المعلم فقال فيه إضطراب . قلت: الرجل ثقة ، وقد احتج به صاحبا الصحيحين، ومات في حدود سنة خمسين ومائة . وذكر له العقيلي حديثا واحدا ، تفرد بوصله ، وغيره من الحفاظ أرسله، فكان ماذا؟ فليس من شرط الثقة أن لا يَغْلَط أبدا، فقد غلط شعبہ ومالک وناهيك بهما ثقة ونبلا وحسين المعلم ممن وثقه يحيى بن معين ، ومن تقدم مطلقا وهو من كبار ائمة الحديث والله أعلم . انھیں ابو حاتم الرازی ، نسائی اور دیگر لوگوں نے ثقہ کہا ہے۔ اور عقیلی نے اپنی کتاب الضعفاء میں انھیں بلا دلیل ذکر کیا اور کہا: وہ مضطرب الحدیث ہیں۔ ابوبکر بن خلاد کہتے ہیں کہ میں نے یحییٰ بن سعید القطان سے سنا جس وقت ان کے سامنے حسین المعلم کا ذکر ہوا تو انھوں نے فرمایا: اس میں اضطراب پایا جاتا ہے۔ میں (ذہبی) کہتا ہوں کہ وہ ثقہ آدمی ہیں۔ ان سے امام بخاری اور امام مسلم نے اپنی اپنی “الصحیح” میں حجت پکڑی ہے۔ اور وہ ۱۵۰ھ کی حدود میں فوت ہوئے۔ امام عقیلی نے ان کے حوالے سے ایک حدیث بیان کی جسے موصول بیان کرنے میں وہ منفرد ہیں جب کہ دیگر حفاظ نے اس حدیث کو مرسل بیان کیا ہے۔ لیکن یہ کوئی ایسی بات نہیں، کیوں کہ کسی راوی کے ثقہ ہونے کے لیے یہ کوئی شرط نہیں کہ وہ کبھی غلطی نہ کرے بلاشبہ امام شعبہ اور مالک سے بھی غلطیاں ہوئی ہیں اور آپ کے لیے یہی کافی ہے کہ یہ دونوں ثقہ اور عظیم المرتبت لوگ ہیں حسین المعلم ان لوگوں میں سے ہیں جنھیں امام یحیی بن معین اور دیگر لوگوں نے جن کا ذکر پہلے ہو چکا ہے، ثقہ قرار دیا ہے اور وہ کبار ائمہ حدیث میں سے ہیں ۔ واللہ اعلم ۔ سیر اعلام النبلاء : (۵۰۴/۵)،(۵۰۵) حافظ ابن حجر رحمہ اللہ (المتوفی : ۸۵۲ھ) فرماتے ہیں: الحسين بن ذكوان المعلم البصرى، وثقه ابن معين والنسائي وأبوحاتم وأبو زرعة والعجلي وابن سعد والبزار والدارقطني ، وقال يحيى القطان فيه إضطراب . قلت: لعل الإضطراب من الرواة عنه فقد احتج به الأئمة . “ حسین بن ذکوان المعلم البصری ان کو ابن معین ، نسائی، ابو حاتم ، ابو زرعہ، عجلی، ابن سعد، بزار اور دارقطنی نے ثقہ کہا ہے اور یحییٰ بن القطان کہتے ہیں کہ اس کی احادیث میں اضطراب ہے۔ میں کہتا ہوں کہ ممکن ہے کہ یہ اضطراب (حسین کی طرف سے نہیں بلکہ ) ان سے بیان کرنے والے راویوں کی طرف سے ہو کیوں کہ ان سے آئمہ نے حجت پکڑی ہے۔‘ (هدی الساري ، ص : ۵۶۶) معلوم ہوا کہ حسین بن ذکوان المعلم ثقہ ہیں۔ کبار آئمہ حدیث نے ان کی توثیق فرمائی ہے۔ حسین کی توثیق کے لیے تو اتنا ہی کافی ہے کہ حضرات شیخین نے ”الصحیحین میں ان سے روایات نقل کی ہیں۔ ان کبار آئمہ کی اس زبر دست توثیق کے مقابلے میں امام عقیلی اور ابن القطان رحمہما اللہ کے قول کی بھلا کیا حیثیت رہ جاتی ہے۔ اعتراض نمبر (۳) امام ترمذی فرماتے ہیں: \" ولا يصح في هذا الباب عن النبي صلى الله عليه وسلم” “زیورات کی زکوۃ کے سلسلے میں نبی صلی اللہ علیہ وسلم سے کچھ ثابت نہیں ہے۔” (سنن الترمذی ، تحت حدیث: ۶۳۷) جواب: ابن القطان الفاسی رحمہ اللہ (المتوفی : ۶۲۸ ھ ) امام ترمذی کی اس بات کا بایں الفاظ جواب دیتے ہیں: \" والترمذي إنما ضعف حديث عبد الله بن عمرو لأنه وقع له من رواية ابن لهيعة والمثنى بن الصباح عن عمرو فضعفهما وضعفه بهما لا بعمرو بن شعيب وللحديث إسناد صحيح إلى عمرو بن شعيب“ اور امام ترمذی نے حدیث عبد اللہ بن عمرو کو صرف اور صرف اس لیے ضعیف کہا ہے کہ ان تک یہ حدیث ابن لہیعہ اور مثنی بن صباح کی سند سے پہنچی ہے اس لیے انھوں نے اسے ضعیف کہا اور انھی دو (ابن لہیعہ اور مثنی بن صباح) کی وجہ سے ضعیف کہا، عمرو بن شعیب کی وجہ سے ضعیف نہیں کہا۔ اور اس حدیث کی عمرو بن شعیب تک سند صحیح ہے۔بیان الوهم والابهام : (۳۶۵/۵)،(۳۶۶) علامہ ابن ملقن رحمہ اللہ (المتوفی : ۸۰۴ھ) فرماتے ہیں: \" و هذا من الترمذي رحمه الله إنما ذكره لأنه لم يقع له الحديث إلا من طريق المثنى بن الصباح وابن لهيعة عن عمرو، والإفله طريقة أخرى صحيحة رواها أبوداود والنسائي من حديث حسين المعلم . “ امام ترمذی نے یہ بات اس لیے ذکر کی ہے کیوں کہ ان کے پاس یہ حدیث صرف مثنی بن صباح اور ابن لہیعہ عن عمرو کی (ضعیف) سند سے پہنچی تھی وگرنہ اس حدیث کی ایک دوسری سند بھی ہے جو بالکل صحیح ہے اسے امام ابوداؤد اور امام نسائی نے حسین المعلم سے نقل کیا ہے۔“ (البدر المنير : ۵۶۵/۵) محدث مبارک پوری رحمہ اللہ (المتوفی : ۱۳۵۳ھ) فرماتے ہیں: \"قلت: فظهر أن قول الترمذي: لا يصح في هذا عن النبي صلى الله عليه وسلم شيء ، غير صحيح والله أعلم ” میں کہتا ہوں کہ امام ترمذی کا یہ کہنا کہ اس مسئلہ میں نبی صلی اللہ علیہ وسلم سے کوئی حدیث صحیح ثابت نہیں، غیر صحیح ہے۔ واللہ اعلم ( تحفۃ الاحوذی : ۳۲۷/۳) دلیل نمبر (۲): ثقہ مخضرم تابعی عبد اللہ بن شداد بن ہاد کہتے ہیں کہ ہم ام المومنین سیدہ عائشہ رضی اللہ عنہا کے پاس گئے تو انھوں نے بیان کیا: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صلى الله عليه وسلم، فَرَأَى فِي يَدَيَّ فَتَخَاتٍ مِنْ وَرِقٍ، فَقَالَ: ((مَا هَذَا يَا عَائِشَةُ؟)) فَقُلْتُ: صَنَعْتُهُنَّ أَتَزَيَّنُ لَكَ يَا رَسُولَ اللهِ قَالَ: ((أَتُؤَدِّينَ زَكَاتَهُنَّ؟)) قُلْتُ : لا ، أَوْ مَا شَاءَ اللهُ ، قَالَ: ((ہُوَ حَسْبُکِ مِنَ النَّارِ))۔ رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے ، آپ نے دیکھا کہ میرے ہاتھوں میں چاندی کی (موٹی موٹی) انگوٹھیاں ہیں تو آپ نے پوچھا: \"عائشہ ! یہ کیا ہے؟“ میں نے عرض کیا: میں نے انھیں آپ کی خاطر زینت کے لیے پہنا ہے، اے اللہ کے رسول ! آپ نے فرمایا: \"کیا تم ان کی زکوۃ دیتی ہو؟ میں نے کہا: نہیں، یا اسی طرح کی کوئی بات کی۔ آپ نے فرمایا: ” تجھے جہنم میں لے جانے کے لیے یہی کافی ہے۔” (سنن ابی داؤد، ح: ۱۵۶۵) اس کی سند حسن ہے۔ اسے امام حاکم نے \"صحیح علی شرط الشیخین“ کہا ہے۔ امام ذہبی نے ان کی موافقت کی ہے۔ (المستدرک: ۳۹۰/۱) امام بیہقی نے \"هذا إسناد حسن” کہا ہے۔ (السنن الصغری، ح: ۵۴۲) حافظ ابن حجر نے ”إسناده على شرط الصحیح“ کہا ہے۔(تلخیص الحبیر: ۳۹۰/۲) یہ حدیث بھی زیورات کی زکوۃ کے وجوب کی دلیل ہے۔ امام ابو داؤد نے اسے “باب الکنز ما ہو؟ وزکاة الحلی” امام دارقطنی نے “باب زكاة الحلي”، امام بیہقی نے ”باب زكاة الحلي“ میں بیان کیا ہے۔ (دیکھیے: سنن ابی داؤد قبل حدیث: ۱۵۶۳، سنن الدارقطنی قبل حدیث: ۱۹۳۴، السنن الصغری قبل حدیث: ۵۴۰) علامہ محمد بن اسماعیل الصنعانی (المتوفی : ۱۱۸۲ھ) فرماتے ہیں: ” والحدیث دليل على وجوب الزكاة في الحلي” “یہ حدیث زیورات میں زکوۃ کے وجوب پر دلیل ہے۔“ (سبل السلام : ۲۳۲/۲) اعتراض نمبر (۱): امام دارقطنی نے فرمایا کہ اس کی سند میں محمد بن عطا مجہول ہے۔ جواب علامہ منذری (المتوفی: ۶۵۶ھ) فرماتے ہیں: ” ولا اعتبار بما ذكره الدارقطني من ان محمد بن عطاء مجهول، فإنه محمد بن عمر بن عطاء نسب إلى جده وهو ثقة روى له أصحاب السنن واحتج به الشيخان في صحيحهما . “ امام دارقطنی کا یہ بیان کہ محمد بن عطا مجہول ہے، لائق التفات نہیں کیوں کہ محمد بن عمر بن عطا اپنے دادا کی طرف منسوب ہے، ثقہ ہے۔ اصحاب سنن نے اس سے روایات نقل کی ہیں، حضرات شیخین نے “الصحیحین” میں اس سے حجت پکڑی ہے۔ (الترغیب والترہیب : ۶۰۳/۱) علامہ منذری رحمہ اللہ کی یہ بات سو فیصد درست ہے کہ محمد بن عطا سے مراد محمد بن عمر بن عطاء ہے۔ سنن ابوداؤد کی سند میں محمد بن عمر بن عطاء ہی ہے اور یہ ثقہ راوی ہے۔ اعتراض نمبر (۲): اس کی سند میں یحیی بن ایوب الغافقی ہے جو منکر روایتیں بیان کرتا ہے۔ جواب محدثین کرام کا یحیی بن ایوب الغافقی کی جرح و تعدیل کے بارے میں اختلاف ضرور ہے لیکن جمہور کے نزدیک وہ ثقہ و صدوق ہیں۔ امام مسلم اپنی “الصحیح” میں ان سے روایات لائے ہیں اور امام بخاری نے اپنی “الصحیح” میں بطور استشہاد ان سے حجت پکڑی ہے۔ جمہور کی تعدیل کے مقابلے میں بعض آئمہ کی جرح مرجوح ہے۔ معتدل امام ابن عدی (المتوفی : ۳۶۵ھ) فرماتے ہیں: \"و یحیی بن أيوب له أحاديث صالحة ..... ولا أرى في حديثه إذا روى عنه ثقة أو يروي هو عن ثقة حديثا منكرا فأذكره وهو عندي صدوق لا بأس به” “یحیی بن ایوب کی احادیث درست ہیں ... اور میں نے اس کی حدیث میں جب اس سے ثقہ راوی روایت کرے یا وہ خود ثقہ سے روایت کرے کوئی منکر حدیث نہیں دیکھی وہ جس کا میں تذکرہ کروں اور وہ میرے نزدیک صدوق ہے۔ اس میں کوئی خرابی نہیں ہے۔“ (الکامل : ۵۹/۹) امام ابن عدی رحمہ اللہ کی اس بات سے معلوم ہوا کہ یحیی بن ایوب کی مرویات میں منکر روایت کا امکان اس وقت ہوتا ہے جب اس کے شیوخ یا شاگردوں میں کوئی غیر ثقہ راوی آئے بصورت دیگر اس کی حدیث صالح ہے۔ ابوداؤد کی مذکورہ روایت میں یحیی کے شیخ عبید اللہ بن ابی جعفر ثقہ ہیں اور ان کے شاگرد عمرو بن ربیع بن طارق بھی ثقہ ہیں۔ والحمد للہ اعتراض نمبر (۳): اس حدیث کو روایت کرنے والی سیدہ عائشہ رضی اللہ عنہا کا اپنا عمل اس کے خلاف تھا وہ زیورات کی زکوۃ نہیں دیتی تھیں، جس کا صاف مطلب یہی ہے کہ یا تو یہ حدیث صحیح نہیں اور یا پھر منسوخ ہو چکی ہے۔ جواب ... سیدہ عائشہ رضی اللہ عنہا زیورات میں زکوۃ کی قائل تھیں۔ وہ فرماتی ہیں: \"لا بَأْسَ بِلبْسِ الْحُلِيِّ إِذَا أَعْطَيْتَ زَكَاتَہ” “زیورات پہنے میں کوئی حرج نہیں جب ان کی زکوۃ ادا کر دی جائے ۔ (سنن الدارقطنی، ح: ۱۹۳۸، الاموال لابی عبید، ح: ۱۲۶۵، واللفظ لہ، وإسنادہ حسن) اس روایت سے پتا چلا کہ سیدہ عائشہ رضی اللہ عنہا زیورات کی زکوۃ کی قائل تھیں۔ باقی جس روایت میں آتا ہے کہ سیدہ عائشہ رضی اللہ عنہا اپنی یتیم بھتیجیوں کے زیورات میں سے زکوۃ نہیں نکالتی تھیں تو اس کا جواب دیتے ہوئے حافظ ابن حجر (المتوفی : ۸۵۲ھ) فرماتے ہیں: \"ويمكن الجمع بينهما بأنها كانت ترى الزكاة فيها ولا ترى إخراج الزكاة مطلقا عن مال الأيتام” “اور ان دونوں روایتوں میں جمع وتطبیق ممکن ہے اور وہ یہ ہے کہ آپ رضی اللہ عنہا زیور میں زکوۃ کی قائل ہوں مگر یتیموں کے مال میں سے مطلقاً زکوۃ کی قائل نہ ہوں۔“ (التلخیص الحبیر: ۳۹۰/۲، الشاملہ) اور یہ بھی ممکن ہے کہ یتیموں کے وہ زیورات جن کی سیدہ عائشہ رضی اللہ عنہا زکوۃ نہیں نکالتی تھیں وہ حد نصاب کو نہ پہنچے ہوں۔ آخر میں شیخ البانی (المتوفی: ۱۴۲۰ھ) کا تبصرہ بھی ملاحظہ فرمائیں، شیخ فرماتے ہیں: \"فهذا الحديث صريح في إيجاب الزكاة على الحلي وهو حجة الذين ذهبوا إلى إيجابه ومنهم الحنفية ، ثم إنه قد ورد عن عائشة نفسها ما يعارض هذا الحديث وهو ما أخرجه مالك (۲۴۵/۱) عن القاسم ابن محمد (راوی) حديث الخاتم أن عائشة كانت تلي بنات أخيها يتامى في حجرها لهن الحلي فلا تخرج من حليهن الزكاة، سندہ صحیح جداً، وتقدم نحوه من رواية أحمد ، فهذه مخالفة صريحة عن عائشة لحديثها ، فإذا جاز في حقها ذلك فبالأحرى ان تخالف حديث غيرها ثم ترويه هي وهي على كل حال مأجورة فماذا يقول المشار إليه في هذه المخالفة؟ أيدع الحديث والمذهب لقولها أم يتمسك بالحديث ويدع قولها معتذرا عنها بأي عذر مقبول كما هو الواجب؟ وعلى كل حال فقد ظهر لكل من له قلب أن ما كان يظنه مما (لا يتصور) أو أنه (مستحيل قطعا) قد أثبتناه بالأسانيد الصحيحة ولازم ذلك أن لا يلتفت المسلم إلى أي قول يخالف ما ثبت عنه مهما كان شانه قائله فضلا وعلما وصلاحا لانتفاء العصمة وهذا من الأسباب التي تشجعنا على الإستمرار في خطتنا من التمسك بالكتاب والسنة وعدم الاعتداد بما سواهما .\" یہ حدیث زیورات پر زکوۃ کے وجوب کے سلسلے میں بڑی واضح ہے اور یہ ان لوگوں کی دلیل ہے جو زیورات میں زکوۃ کے وجوب کے قائل ہیں جن میں حنفیہ بھی شامل ہیں۔ دوسری طرف سیدہ عائشہ رضی اللہ عنہا کا اپنا عمل اس حدیث کے معارض وارد ہوا ہے۔ اسے امام مالک نے الموطا (۲۴۵/۱) میں “حدیث خاتم” کے راوی قاسم ابن محمد سے روایت کیا ہے کہ سیدہ عائشہ رضی اللہ عنہا کی بھتیجیاں ان کی زیر کفالت تھیں، ان کے زیورات بھی تھے لیکن سیدہ عائشہ رضی اللہ عنہا ان کی زکوۃ نہیں دیتی تھیں۔ اس اثر کی سند انتہا درجے کی صحیح ہے اور ایسی ہی ایک روایت مسند احمد کے حوالے سے بھی گزر چکی ہے، تو عائشہ رضی اللہ عنہا کی جانب سے اپنی ہی بیان کردہ حدیث کی یہ صریح ترین مخالفت ہے۔ لہذا جب ان کا (اپنی روایت کردہ حدیث کی) اپنے حق میں مخالفت کرنا جائز ہے تو پھر ان کا اس روایت کی مخالفت کرنا زیادہ لائق ہے جو انھوں نے روایت ہی نہیں کی۔ بہر حال وہ ماجور ہیں۔ اب مشار الیہ اس مخالفت کے متعلق کیا کہے گا؟ کیا سیدہ عائشہ رضی اللہ عنہا کے قول کی وجہ سے حدیث اور مذہب کو چھوڑ دیا جائے گا یا پھر حدیث کو مضبوطی سے پکڑا جائے اور ان کے قول کو کسی عذر پر محمول کرتے ہوئے ترک کر دیا جائے گا جیسا کہ یہ ضروری بھی ہے؟ بہر حال ہر صاحب دل کے لیے یہ بات واضح ہوگئی ہے کہ جس چیز کا وہ تصور بھی نہیں کر سکتا تھا یا اس کو وہ محال سمجھتا تھا ہم نے اسے صحیح اسانید کے ساتھ ثابت کر دیا ہے اور یہ ضروری ہے کہ مسلمان رسول اللہ صلی اللہ علیہ وسلم سے ثابت ہونے والی بات کے مخالف کسی بھی قول کی طرف متوجہ نہ ہوا اگر چہ کہنے والا کتنا ہی صاحب فضل وشان اور علم والا ہو، وجہ اس کی واضح ہے کہ امتیوں میں سے کسی کو بھی عصمت حاصل نہیں اور یہ چیز ان اسباب میں شامل ہے جو ہمیں ہماری تحریر میں ابھارتی ہے کہ ہم کتاب وسنت کو مضبوطی سے تھامے رکھیں ۔“ آداب الزفاف ، ص: (۱۹۲)،(۱۹۳)، الشاملہ ، یہ شیخ البانی رحمہ اللہ کا جواب تھا جو ہم نے بیان کر دیا۔ اوپر ہم سیدہ عائشہ رضی اللہ عنہا کی دونوں روایتوں میں جمع و تطبیق بیان کر چکے ہیں۔ اب جس کا دل چاہے وہ پائے روشنی، ہم نے تو دیا جلا کر سرعام رکھ دیا دلیل نمبر (۳): بعض لوگ وہ آیات و احادیث بھی دلیل بناتے ہیں جن میں مطلقاً سونے وچاندی کی زکوۃ دینے کا حکم آیا ہے۔ کیوں کہ ان کے عموم میں زیورات بھی شامل ہیں جیسا کہ ایک آیت میں ہے: وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيْلِ اللهِ فَبَشِّرُهُمْ بِعَذَابٍ أَلِيمٍ (التوبة : ۳۴) اور جو لوگ سونے اور چاندی کو خزانہ بنا کر رکھتے ہیں اور اسے اللہ کی راہ میں خرچ نہیں کرتے ، تو انھیں دردناک عذاب کی بشارت سنادے۔“ اور ایک حدیث میں ہے: ((مَا مِنْ صَاحِبِ ذَهَبٍ وَلَا فِضَّةٍ لَا يُؤَدِّي مِنْهَا حَقَّهَا إِلَّا إِذَا كَانَ يَوْمُ الْقِيَامَةِ صُفْحَتْ لَهُ صَفَائِحُ مِنْ نَّارٍ فَأَحْمِيَ عَلَيْهَا فِي نَارِ جَهَنَّمَ فَيُكُوى بِهَا جَنْبُهُ وَجَبِينُهُ وَظَهْرُهُ كُلَّمَا بَرَدَتْ أُعِيدَتْ لَهُ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ يُقْضَى بَيْنَ الْعِبَادِ فَيَرى سَبِيلَهُ إِمَّا إِلَى الْجَنَّةِ وَإِمَّا إِلَى النَّارِ۔\" جو سونے اور چاندی کا مالک اس کا حق ادا نہیں کرتا جب قیامت کا دن ہوگا تو اس کے لیے آگ کی تختیاں بنائی جائیں گی اور انھیں جہنم کی آگ میں تپایا جائے گا اور پھر ان کے ساتھ اس کے پہلو، اس کی پیشانی اور اس کی پشت کو داغا جائے گا جب وہ تختیاں ٹھنڈی ہو جائیں گی تو انھیں گرم کرنے کے لیے دوبارہ جہنم میں لوٹا دیا جائے گا اور یہ عمل اس روز مسلسل جاری رہے گا جس کی مقدار پچاس ہزار سال ہوگی حتی کہ بندوں کے درمیان فیصلہ کر دیا جائے اور وہ جنت یا جہنم کی طرف اپنا راستہ دیکھ لے۔ (صحیح مسلم، ح: ۹۸۷) دلیل نمبر (۴): بہت سارے تابعین کا بھی یہی مذہب ہے کہ زیورات میں زکوۃ واجب ہے۔ چنانچہ: مشہور ثقہ تابعی امام عطاء بن ابی رباح فرماتے ہیں: \"إذا بلغ الحلي ما تجب فيه الزكاة، ففيه الزكاة” “جب زیورات اس مقدار کو پہنچ جائیں جس پر زکوۃ واجب ہوتی ہے تو پھر ان ( زیورات) میں بھی زکوۃ ( واجب) ہے ۔ (المصنف لابن ابی شیبہ، ح: ۱۰۲۷۰، وسنده صحيح) جلیل القدر تابعی امام ابن سیرین زیورات کی زکوۃ کے سلسلے میں فرماتے ہیں: “في عشرين مثقالا نصف مثقال، وفي أربعين مثقالا مثقال” “بیس مثقال میں نصف مثقال اور چالیس مثقال میں ایک مثقال (زکوۃ) ہے۔ (کتاب الاموال لابی عبید، ح: ۱۲۷۲ وسنده صحيح) ثقہ و صدوق محدث جعفر بن برقان کہتے ہیں کہ میں نے میمون بن مہران سے زیورات کی زکوۃ کے بارے میں پوچھا تو انھوں نے فرمایا: \"إن لنا طوقا لقد زكيته حتى أتى على نحو ثمنه” “بے شک ہمارا ایک ہار ہے میں نے تو اس کی بھی زکوۃ ادا کی ہے حتی کہ وہ اپنی قیمت پر آگیا۔ (یعنی ادا کی ہوئی ہر سال کی زکوۃ اس ہار کی قیمت کے قریب قریب پہنچ گئی ہے) (ایضاً، ح: ۱۲۷۴، وسندہ صحیح)۔ ثقہ فقیہ تابعی ابراہیم نخعی فرماتے ہیں: “فى الحلی زکاة ”زیورات میں زکوۃ ہے۔“ (المصنف لابن ابی شیبہ، ح: ۱۰۲۶۰ وسنده صحيح) ثقہ محدث عمرو بن ہرم کہتے ہیں: “سئل جابر ابن زید هل في الحلي زكاة؟ قال: نعم، إذا كان عشرين مثقالا أو مئتي درهم . ” جابر ابن زید سے پوچھا گیا کہ کیا زیورات میں زکوۃ ہے؟ انھوں نے کہا: جی ہاں۔ جب وہ بیس مثقال یا دو سو درہم کو پہنچ جائیں ۔ (ايضاً، ح: ۱۰۲۶۶ وسنده صحيح) عدم وجوب کے دلائل: دلیل نمبر (۱): بعض صحابہ کرام رضی اللہ عنہم زیورات کی زکوۃ کے قائل نہ تھے۔ امام نافع فرماتے ہیں: \" أن عبد الله بن عمر كان يحلي بناته وجواريه الذهب ثم لا يخرج من حليهن الزكاة” “سیدنا عبد اللہ بن عمر رضی اللہ عنہ اپنی بیٹیوں اور لونڈیوں کو سونے کے زیورات پہناتے تھے پھر ان کے زیورات سے زکوۃ نہیں نکالتے تھے ۔ (الموطا للامام مالک، ح: ۵۸۵ وسنده صحيح) ثقہ تابعی عمرو بن دینار کہتے ہیں: “سئل جابر بن عبد الله أفى الحلي زكاة؟ قال: لا، قيل: وإن بلغ عشرة آلاف؟ قال: کثیر۔” سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے پوچھا گیا کہ کیا زیورات میں زکوۃ ہے؟ انھوں نے فرمایا: نہیں۔ کہا گیا: خواہ وہ (زیورات) ایک ہزار کو پہنچ جائیں؟ فرمایا: کثیر (ایک ہزار تو بہت زیادہ ہے)۔” (کتاب الاموال لابی عبید، ح: ۱۲۷۵، وسندہ صحیح) فاطمہ بنت منذر، سیدہ اسماء سے روایت کرتی ہیں: “أنها كانت تحلي بناتها الذهب ولا تزكيه” “وہ (اسماء رضی اللہ عنہا) اپنی بیٹیوں کو سونے کا زیور پہناتی تھیں اور اس کی زکوۃ نہیں نکالتی تھیں۔“ (المصنف لابن ابی شیبہ، ح: ۱۰۲۷۷ وسنده صحیح) ثقہ فقیہ تابعی قاسم بن محمد کہتے ہیں: أن عائشة زوج النبي صلى الله عليه وسلم كانت تلي بنات أخيها يتامى في حجرها لهن الحلي، فلا تخرج من حليهن الزكاة” “ام المومنین سیدہ عائشہ رضی اللہ عنہا کی تولیت میں ان کی یتیم بھتیجیاں تھیں، ان کے زیورات بھی تھے وہ ان کے زیورات کی زکوۃ نہیں نکالتی تھیں ۔ (الموطا للامام مالک، ح: ۵۸۴، وسندہ صحیح) سیدہ عائشہ رضی اللہ عنہا کا اپنی یتیم بھتیجیوں کے زیورات میں سے زکوۃ نہ نکالنے کی وضاحت گزشتہ سطور میں ہو چکی ہے۔ یاد رہے کہ سیدنا انس بن مالک رضی اللہ عنہ سے بھی یہ چیز مروی ہے کہ انھوں نے فرمایا: \"ليس فيه زكاة” “زیورات میں زکوۃ نہیں۔ (سنن الدارقطنی، ح: ۱۹۴۶) مگر اس کی سند ضعیف ہے۔ علی بن سلیم کو صرف ابن حبان نے ثقہ کہا ہے۔ جب کہ شریک نخعی مدلس و مختلط ہے۔ دلیل نمبر (۲) بعض تابعین بھی زیورات کی زکوۃ کے قائل نہ تھے۔ امام حسن بصری فرماتے ہیں: \" لا نعلم أحد من الخلفاء قال في الحلي زكاة. ہم خلفاء میں سے کسی کو نہیں جانتے جس نے زیورات میں زکوۃ کا کہا ہو۔“ (المصنف لابن ابی شیبہ، ح: ۱۰۲۷۹، وسندہ حسن) یحیی بن سعید انصاری کہتے ہیں : “سألت عمرة عن زکاة الحلی فقالت: ما رأیت أحداً یزکیہ۔” “میں نے عمرہ سے زیورات کی زکوۃ کے متعلق پوچھا تو انھوں نے فرمایا: میں نے کسی کو ان کی زکوۃ نکالتے نہیں دیکھا۔ (ایضاً، ح: ۱۰۲۷۸ وسنده صحيح) عمرہ بنت عبد الرحمن نے کسی کو زیورات کی زکوۃ نکالتے نہیں دیکھا ورنہ بہت سارے تابعین زیورات کی زکوۃ کے قائل تھے۔ علاوہ ازیں زکوۃ دکھا کر نکالنی تو ضروری نہیں ہے۔ دلیل نمبر (۳): بعض کبار اہل علم کا بھی یہی موقف ہے۔ امام محمد بن علی الباقر فرماتے ہیں: \"لیس فی الحلی زکاة۔” “زیورات میں زکوۃ نہیں ہے۔“ (المصنف لابن ابی شیبہ، ح: ۱۰۲۸۴، وسنده صحيح) امام مالک بن انس فرماتے ہیں: \" فأما التبر والحلي المكسور الذي يريد أهله إصلاحه ولبسه فإنما هو بمنزلة المتاع الذي يكون عند أهله فليس على أهله فيه زكاة.” “ہاں چاندی کے ٹکڑے اور شکستہ زیورات جنھیں مالک مرمت اور درستی کے بعد استعمال کرنے کا ارادہ رکھتا ہے، گھر کے عام سامان کی طرح ہے اس میں مالک پر کوئی زکوۃ نہیں ہے۔“ (المؤطا، ص : ۱۵۹) امام ابو داؤد فرماتے ہیں کہ میں نے امام احمد بن حنبل کو فرماتے سنا: “الحلي ليس عندنا فيه زكاة.” “ہمارے نزدیک زیورات میں زکوۃ نہیں ہے۔ امام ابوداؤد فرماتے ہیں: اور ایک مرتبہ میں نے امام احمد کو یہ فرماتے سنا: “زکاتہ أن یعار ویلبس” زیورات کی زکوۃ یہی ہے کہ انھیں عاریتاً دیا جائے اور پہنا جائے ۔ مسائل الإمام أحمد : (۵۴۹)،(۵۵۰) راجح: راجح مسلک وہی ہے جو ہم شروع میں بیان کر چکے ہیں کہ سونا و چاندی کے زیورات اگر نصاب کو پہنچ جائیں تو ان پر زکوۃ واجب ہے، کیوں کہ: وجوب کے دلائل مضبوط اور قوی ہیں۔ محمد بن اسماعیل امیر صنعانی (المتوفی: ۱۱۸۲ھ ) رقم طراز ہیں: “وأظهر الأقوال دليلا وجوبها لصحة الحديث وقوته.” “تمام اقوال میں سے دلیل کے لحاظ سے سب سے غالب قول اس کے وجوب کا ہے جس کی وجہ حدیث کا صحیح اور قوی ہونا ہے۔“ (سبل السلام : ۲۳۲/۲) یہ موقف کتاب وسنت کے ظاہر کے ساتھ زیادہ مشابہت رکھتا ہے۔ امام بیہقی (المتوفی: ۴۵۸ھ) فرماتے ہیں: \"وهذا أشبه بظاهر الكتاب والسنة.” “اور یہ (موقف) کتاب وسنت کے ظاہر سے بہت زیادہ ملتا جلتا ہے۔\" (السنن الصغری، کتاب الزکاة، باب زکاة الحلی: ۱۰۵/۲) اس میں احتیاط ہے کہ زیورات کی زکوۃ دی جائے۔ علامہ خطابی (المتوفی : ۳۸۸ھ) فرماتے ہیں: \"قلت: الظاهر من الكتاب يشهد لقول من أوجبها والأثر يؤيده ومن اسقطها ذهب إلى النظر، ومعه طرف من الاثر ، والاحتياط أداؤها، والله أعلم . \" میں کہتا ہوں کہ کتاب کا ظاہر اس شخص کے موقف کی تائید کرتا ہے جس نے زیورات کی زکوۃ کو واجب کہا، حدیث بھی اس کی موید ہے۔ اور جس نے اس کو ساقط کیا (یعنی یہ کہا کہ زیورات پر زکوۃ نہیں) وہ تحقیقی موقف کی طرف گیا حدیث اس کی بھی تائید کرتی ہے جب کہ احتیاط اس کی ادائیگی ہی میں ہے۔ واللہ اعلم۔ (مختصر سنن ابی داؤد للمنذری ومعالم السنن للخطابی: ۱۷۶/۲) شیخ محمد الامین الشنقیطی (المتوفی: ۱۳۹۳ھ) فرماتے ہیں: \" وإخراج زكاة الحلي أحوط لأن من اتقى الشبهات فقد استبرأ لدينه وعرضه ودع ما يريبك إلى ما لا يريبك والعلم عند الله تعالى .“ زیادہ احتیاط والا مسلک یہ ہے کہ زیورات کی زکوۃ ادا کی جائے کیوں کہ جو شبہات سے بچا اس نے اپنا دین اور عزت و آبرو کو محفوظ کر لیا۔” “اور شبہ والی چیز کو چھوڑ کر اس چیز کو اختیار کرنا چاہیے جس میں کوئی شبہ نہ ہو۔” (تفسیر اضواء البیان: ۴۱/۱۰) جن تین صحابہ (سیدنا ابن عمر، جابر بن عبد اللہ اور سیدہ اسماء رضی اللہ عنہم) سے عدم وجوب کا قول مروی ہے، وہ مجتہد ہیں اور عند اللہ ماجور ہیں۔ ممکن ہے کہ ان تک نبی صلی اللہ علیہ وسلم کی حدیث نہ پہنچی ہو۔ بہرحال! زیورات کی زکوۃ ادا کرنی چاہیے۔ اس کے دلائل مضبوط اور قوی ہیں۔ شیخ ابن جریر فرماتے ہیں: بلاشبہ استعمال ہونے والے زیورات کی زکوۃ کے بارے میں قدیم وجدید ہر دور میں بہت اختلاف رہا ہے لیکن میرے نزدیک مختار قول یہ ہے کہ ہر سال زیورات کی زکوۃ ادا کرنا لازم ہے۔ خواہ خواتین پہنتی ہی کیوں نہ ہوں کیوں کہ اس کے دلائل بہت قوی ہیں۔ زکوۃ ادا کرتے وقت ان کی موجودہ قیمت کا حساب لگایا جائے گا اور اس کے حساب سے زکوۃ ادا کی جائے گی، یہ نہیں دیکھا جائے گا کہ ان کی قیمت خرید کیا تھی ، خواہ وہ کم تھا یا زیادہ اور پھر کل قیمت کا چالیسواں حصہ ( یعنی اڑھائی فیصد ) بطور زکوۃ ادا کر دیا جائے گا۔ واللہ اعلم۔ (فتاوی اسلامیہ: ۱۲۲/۲) شیخ ابن باز رحمہ اللہ (المتوفی: ۱۴۲۰ھ) فرماتے ہیں: عورتوں کے زیورات جب کہ وہ نصاب کے مطابق ہوں اور بغرض تجارت نہ ہوں تو ان میں وجوب زکوۃ کے بارے میں اہل علم میں اختلاف ہے لیکن صحیح بات یہی ہے کہ ان میں زکوۃ واجب ہے بشرطیکہ وہ نصاب کے مطابق ہوں خواہ محض پہنے اور زیب و زینت کے لیے ہوں۔ (مقالات و فتاوی، ص: ۲۵۹) شیخ البانی رحمہ اللہ (المتوفی: ۱۴۲۰ھ) فرماتے ہیں: ” درست بات یہ ہے کہ عورتوں کے زیورات پر زکوۃ ہے۔” (فتاوی البانیہ، ص: ۲۱۳)"}],[637,"امام سفیان ثوری فرماتے ہیں: اگر میں کسی (متقی) نوجوان کی صحبت اختیار کروں تو یہ مجھے اس بات سے زیادہ محبوب ہے کہ میں کسی (بے عمل) قاری کی صحبت اختیار کروں۔","",{"t":"متقی لوگوں کی صحبت","k":"حسن: مسند ابن الجعد، ح: 1828۔ العزلة للخطابي، ح: 217۔","f":"بے عمل عالم سے با عمل نوجوان بہتر ہے۔\nبا عمل افراد کی صحبت میں وقت گزارنے کی کوشش کرنی چاہیے۔"}],[638,"امام حسن بصری فرماتے ہیں: گردن آزاد کرنا زیادہ حق رکھتا ہے کہ (نیک اعمال میں) اس سے ابتدا کی جائے۔","",{"t":"گردن آزاد کرنا","k":"اسناده صحيح","f":"امام حسن بصری کے اس قول کا مطلب یہ ہے کہ تمام اعمال خیر میں گردن آزاد کرنا یہ عمل سب سے زیادہ حق رکھتا ہے کہ اس سے ابتدا کی جائے یعنی جب کسی کے پاس ہر قسم کی نیکی کے حصول کے اسباب و وسائل موجود ہوں تو وہ گردن آزاد کرنے کو تمام اعمال پر مقدم کرے۔ واللہ اعلم!"}],[639,"سیدنا انس رضی اللہ عنہ فرماتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کو کبھی نہیں دیکھا کہ آپ نے روزے کی حالت میں مغرب ادا کی ہو یہاں تک کہ افطاری کر لیتے اگر چہ پانی کے ایک گھونٹ ہی سے ہوتی۔","",{"t":"نماز مغرب سے پہلے روزہ افطار کرنا","k":"صحيح: المصنف لابن أبي شيبة، ح: 9882۔ مسند ابی یعلی، ح: 3792۔ صحيح ابن حبان، ح: 3504۔ مسند البزار، ح: 7127۔","f":"نماز مغرب سے پہلے افطاری کرنا مستحب ہے۔\nافطاری کرنے کے بعد نماز مغرب ادا کرنا مستحب ہے۔\nافطاری میں جلدی کرنی چاہیے اگر چہ پانی کا ایک گھونٹ ہی میسر ہو۔"}],[640,"عبد العزیز بن ابی بکرہ بیان کرتے ہیں کہ ابو بکرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے عہد مبارک میں مسجد میں داخل ہوئے جبکہ آپ صلی اللہ علیہ وسلم نماز میں کھڑے تھے۔ فرماتے ہیں: میں دوڑا یہاں تک کہ نبی صلی اللہ علیہ وسلم کے ساتھ نماز میں داخل ہو گیا۔ فرماتے ہیں: پھر جب نبی صلی اللہ علیہ وسلم نے اپنی نماز مکمل کر لی تو آپ نے فرمایا: \"یہ دوڑنے والا کون تھا؟\" ابو بکرہ کہتے ہیں کہ میں نے کہا: اے اللہ کے نبی! میں تھا۔ آپ نے فرمایا: \"اللہ تمہاری حرص میں اضافہ کرے لیکن دوبارہ ایسا نہ کرنا۔\"","",{"t":"صف میں ملنے سے پہلے رکوع کر لینا","k":"إسناده ضعيف: بکار ابو بکرہ بن عبد العزیز کو جمہور نے ضعیف کہا ہے۔ حدیث نمبر 463 اس سے بے نیاز کر دیتی ہے۔"}],[641,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: قریش کے قبیلے بنو مخزوم کی ایک عورت نے چوری کر لی تو اسے نبی صلی اللہ علیہ وسلم کی خدمت میں پیش کیا گیا۔ انہوں (اس کے رشتے داروں) نے کہا: اس کے بارے میں آپ صلی اللہ علیہ وسلم سے کون بات کرے گا؟ انہوں نے کہا: اسامہ بن زید۔ چنانچہ وہ (اسامہ رضی اللہ عنہ) آپ کی خدمت میں حاضر ہوئے اور آپ سے بات کی تو آپ نے انہیں ڈانٹا اور فرمایا: \"بے شک بنی اسرائیل جو تھے جب ان میں کوئی معزز شخص چوری کرتا تو اسے چھوڑ دیتے اور جب ان میں کوئی کمزور شخص چوری کرتا تو اس کے ہاتھ کاٹ دیتے۔ اس ذات کی قسم! جس کے ہاتھ میں میری جان ہے، اگر فاطمہ بنت محمد بھی چوری کرتی تو میں ضرور اس کا ہاتھ بھی کاٹ دیتا۔\"","",{"t":"حدود اللہ میں سفارش کرنا","k":"صحيح البخاري، ح: 6788۔ صحيح مسلم، ح: 1688۔ سنن أبي داؤد، ح: 4373۔ سنن الترمذي، ح: 1430۔ سنن النسائي، ح: 4904۔ سنن ابن ماجه، ح: 2547۔","f":"یہ فتح مکہ کا واقعہ ہے، اس عورت کا ہاتھ کاٹ دیا گیا تھا، سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: پھر اس کے بعد اس عورت نے اچھی توبہ کر لی تھی وہ ہمارے ہاں تشریف لایا کرتی تو میں اس کی ضرورت نبی صلی اللہ علیہ وسلم کی خدمت میں پیش کر دیا کرتی تھی۔ (صحیح البخاری، ح: ۲۶۴۸۔ صحیح مسلم، ح: ۱۶۸۸)\nاسلام میں چوری کی سزا ہاتھ کاٹنا ہے۔\nشریعت موسوی میں بھی چوری کی یہی سزا مقرر تھی۔\nحدود اللہ کو ٹالنے کے لیے سفارش کرنا جائز نہیں۔\nاقوام سابقہ کی بربادی کا ایک سبب ان میں رائج طبقاتی امتیاز تھا یعنی امیر اور غریب کے لیے قانون کا الگ الگ ہونا۔\nحدود اللہ کے نفاذ میں کسی کے لیے کوئی رعایت نہیں۔\nسیدنا اسامہ بن زید رضی اللہ عنہ بڑی قدر و منزلت والے تھے۔"}],[642,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"جس شخص نے سبحان اللہ، لا الہ الا اللہ، اللہ اکبر اور الحمد للہ پڑھا اللہ تعالیٰ اس کے لیے ہر حرف کے بدلے دس نیکیاں لکھ دیتا ہے۔ اور جس نے کسی باطل جھگڑے میں معاونت کی وہ مسلسل اللہ کی ناراضی میں رہے گا یہاں تک کہ وہ (اس جھگڑے سے) الگ ہو جائے۔ اور جس کی سفارش اللہ کی حدود میں سے کسی حد میں حائل ہو گئی تو بلاشبہ اس نے اللہ کی اس کے حکم میں مخالفت کی۔ اور جس نے کسی مومن مرد یا مومن عورت پر تہمت لگائی قیامت کے دن اللہ تعالیٰ اسے \"ردغة الخبال\" میں قید کرے گا یہاں تک کہ وہ اس (بات) سے باہر آ جائے جو اس نے کہی جبکہ وہ کسی صورت باہر آنے والا نہیں ہے۔\"","",{"k":"حسن: دیکھیے: حدیث نمبر 292۔"}],[643,"سیدنا ابو ہریرہ رضی اللہ عنہ فرماتے ہیں: ایک آدمی نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور کہنے لگا: میری لونڈی نے زنا کیا ہے اور اس کا زنا واضح ہو گیا ہے۔ آپ نے فرمایا: \"اسے پچاس کوڑے لگاؤ۔\" پھر وہ آپ کی خدمت میں حاضر ہوا اور کہا: اس نے دوبارہ زنا کیا ہے اور اس کا زنا واضح ہو گیا ہے۔ آپ نے فرمایا: \"اسے پچاس کوڑے لگاؤ۔\" پھر وہ (تیسری بار) آپ کی خدمت میں آیا اور عرض کی: اس نے پھر زنا کیا ہے اور اس کا زنا واضح ہو گیا ہے۔ آپ نے فرمایا: \"اسے فروخت کر دے اگر چہ بالوں کی ایک رسی کے عوض ہی ہو۔\"","",{"t":"زنا کار غلام کی سزا","k":"إسناده ضعيف: شرح مشكل الآثار، ح: 3731۔ السنن الكبرى للنسائي، ح: 7215۔ محمد بن عبد الرحمن ابن ابی لیلی ضعیف ہے، اس میں ایک اور علت بھی ہے۔ صحیح البخاری کی حدیث (2152 عن ابی ہریرہ رضی اللہ عنہ) اس سے بے نیاز کر دیتی ہے۔"}],[644,"سیدنا علی بن ابی طالب رضی اللہ عنہ فرماتے ہیں: اس ذات کی قسم! جس نے دانے کو پھاڑا اور روح کو تخلیق فرمایا، بلاشبہ نبی امی صلی اللہ علیہ وسلم نے مجھے بتا دیا تھا کہ مجھ سے صرف مومن محبت کرے گا اور صرف منافق بغض رکھے گا۔","",{"t":"سیدنا علی رضی اللہ عنہ سے محبت","k":"صحيح مسلم، ح: 78۔ سنن الترمذي، ح: 3736۔ سنن النسائي، ح: 5021۔ سنن ابن ماجه، ح: 114۔","f":"سیدنا علی رضی اللہ عنہ سے ایسی محبت جو غلو و استخفاف سے پاک ہو ایمان کی نشانی ہے اور ان کی عظمت و فضیلت سے حسد کرتے ہوئے ان سے بغض رکھنا نفاق کی علامت ہے۔\nاہل علم کا کہنا ہے کہ اگر کسی ذاتی جھگڑے کی بنا پر کوئی ناراضی ہو تو وہ اس وعید میں نہیں آتا۔ واللہ اعلم!"}],[645,"سیدنا ابو بکرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ ابن بدیل سے ملے تو آپ نے فرمایا: \"میں تو یہی دیکھ رہا ہوں کہ تو فی الواقع قتل کر دیا جائے گا۔ کیا تجھے اپنا وہ خواب یاد ہے جو تو نے دیکھا تھا اور ابوبکر سے بیان کیا تھا؟ انہوں نے کہا تھا کہ اگر تیرا خواب سچا ہوا تو تو ایک خلط ملط معاملے میں قتل کر دیا جائے گا۔ پھر وہ صفین کے دن قتل ہوئے۔\"","",{"t":"خواب اور ان کی تعبیر","k":"صحيح: التاريخ الاوسط للبخاري (575/1)، ح: 306۔ السنة لعبد الله بن احمد، ح: 1289۔","f":"ابن بدیل نے ایک خواب دیکھا تھا جس کی سیدنا ابو بکر صدیق رضی اللہ عنہ نے یہ تعبیر فرمائی تھی کہ تم ایک ملتبس معاملے میں قتل ہو جاؤ گے، چنانچہ ابن بدیل جنگ صفین میں قتل ہوئے یوں ابو بکر رضی اللہ عنہ کی تعبیر سچ ثابت ہوئی۔\nاس میں سیدنا ابو بکر صدیق کی منقبت کا بھی بیان ہے کہ اللہ تعالیٰ نے ان کو خوابوں کی تعبیر کا علم عطا فرما رکھا تھا۔"}],[646,"حکم بن اعرج کہتے ہیں: ایک آدمی سند یا ہند سے ایک شہتیری لایا تو زیاد یا ابن زیاد نے اس سے وہ طلب کی، اس نے اسے فروخت کرنے سے انکار کر دیا تو اس نے وہ اس سے غصب کر کے بصرہ کی مسجد کے چبوترے میں کھڑی کر دی۔ راوی کہتا ہے: ابو بکرہ رضی اللہ عنہ نے اس مسجد میں نماز نہیں پڑھی جب تک کہ اسے اکھیڑ نہیں دیا گیا۔","",{"t":"غصب شدہ چیز مسجد میں استعمال کرنا","k":"اسناده حسن: تاريخ دمشق (215/62)۔","f":"زیاد یا ابن زیاد اس وقت بصرہ کا گورنر تھا جس نے اس آدمی سے زبردستی چھین کر وہ شہتیری مسجد میں لگوائی تھی۔\nسیدنا ابو بکرہ رضی اللہ عنہ کا یہ تقویٰ تھا کہ انہوں نے جب تک وہ شہتیری ہٹا نہیں دی گئی اس مسجد میں نماز نہیں پڑھی۔\nغصب شدہ زمین پر بنائی گئی مسجد یا وہ مسجد جس پر جانتے بوجھتے ہوئے مال حرام صرف کیا گیا ہو کمال تقویٰ کا تقاضا ہے کہ اس میں نماز نہ پڑھی جائے۔"}],[647,"روح بن زنباع کہتے ہیں کہ میں تمیم الداری رضی اللہ عنہ کے پاس آیا اس وقت وہ بیت المقدس پر امیر مقرر تھے اور وہ اپنے گھوڑے کے لیے جو کے چھلکے اتار رہے تھے۔ میں نے کہا: اے امیر! کیا آپ کا کوئی ملازم نہیں جو آپ کو اس کام سے کفایت کر سکے؟ انہوں نے کہا: نہیں، بے شک میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے: \"جس نے اپنے گھوڑے کے لیے جو کے چھلکے اتارے پھر اس کے ساتھ کھڑا ہو یہاں تک کہ اس پر لٹکا دے کہ سفر میں گھوڑے کی خوراک کے طور پر کام دے سکے تو اللہ تعالیٰ اس کے لیے ہر جو کے بدلے ایک نیکی لکھ دیتا ہے۔\"","",{"t":"گھوڑے کی خدمت کرنا","k":"حسن: المعجم الكبير، ح: 1254۔ المعجم الاوسط، ح: 1133۔ المعجم الصغير، ح: 14۔ الصحيحة، ح: 2269۔","f":"گھوڑوں اور دیگر چوپایوں کی خدمت میں اجر و ثواب ہے۔\nسیدنا تمیم الداری رضی اللہ عنہ کی سادگی اور عجز و انکساری تھی کہ وہ امیر ہوتے ہوئے بھی اپنے جانور کے لیے اس کی خوراک کا خود بندوبست کر رہے تھے۔"}],[648,"سیدنا انس بن مالک رضی اللہ عنہ سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت کرتے ہیں انہوں نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے گدی کے بال مونڈنے سے منع فرمایا الا یہ کہ حجامہ لگوانے کے لیے ہو۔ (راوی کہتا ہے) پھر میں نے اس کا تذکرہ ابن ابی السری سے کیا تو انہوں نے کہا: ہمیں عمر بن عبد الواحد نے روح بن محمد سے، انہوں نے قتادہ سے، انہوں نے حسن سے، انہوں نے عمر بن خطاب رضی اللہ عنہ سے بیان کیا، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”حجامہ کے علاوہ گدی منڈوانا مجوسیت ہے۔“ ابن ابی السری نے کہا: پھر میں نے اس کا تذکرہ ولید سے کیا تو انہوں نے کہا: ہمیں ایک آدمی نے قتادہ سے، انہوں نے حسن سے، انہوں نے عمر بن خطاب رضی اللہ عنہ سے بیان کیا، انہوں نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے حجامہ کے علاوہ گدی منڈوانے سے منع فرمایا ہے۔ ابن ابی السری کہتے ہیں: سو ہم یہ سمجھتے ہیں کہ ولید (بن مسلم) نے عمر بن عبد الواحد سے اس میں تدلیس کی ہے۔","",{"t":"گدی کے بال منڈوانا","k":"إسناده ضعيف: المعجم الاوسط، ح: 2969۔ المعجم الصغير، ح: 261۔ الضعيفة، ح: 3496۔ حسن بصری مدلس نے اپنے سماع کی صراحت نہیں کی، اس میں اور بھی علتیں ہیں۔"}],[649,"بقیہ کہتے ہیں کہ شعبہ نے مجھے کہا: سعید بن بشیر صدوق الحدیث ہے۔","",{"t":"سعید بن بشیر الازدی","k":"صحيح: الجرح والتعديل لابن ابي حاتم (143/1)۔ مسند الشاميين، ح: 2564۔","f":"سعید بن بشیر الازدی کو اگرچہ امام شعبہ وغیرہ نے صدوق کہا ہے لیکن اکثر محدثین ان کو ضعیف قرار دیتے ہیں، دیکھیے: البدر المنير لابن ملقن: ۸۵/۹ لہذا وہ ضعیف ہیں۔"}],[650,"شعیب بن اسحاق کہتے ہیں: (میرے پاس) سعید بن بشیر آتا اور کہتا: میرے لیے سعید بن ابی عروبہ کی کتاب نکالو، تو میں وہ (کتاب) نکال کر اسے دیتا، وہ اسے زبانی یاد کر لیتا پھر جا کر اسے بیان کرتا۔","",{"k":"إسناده ضعيف: صاحب کتاب کا شيخ محمد بن وليد مجہول ہے۔"}]]);
